standard-model.automorphisms-preserve-sl:
"""standard-model.automorphisms-preserve-slot-pair-split-are: exact checks.

Two exact models. (GA) Cl(10,0) with generators e_0..e_9, e_0..e_5 the six pair Majoranas and e_6..e_9
the four slot Majoranas. (Fock) The five-mode module as 32 x 32 rational matrices, pair modes 0, 1, 2
and slot modes 3, 4 (the text's 4 and 5); real-form Majoranas g_{2m} = v_m + w_m, g_{2m+1} = w_m - v_m
(the text's gamma_{2m+1} = I g_{2m+1}, I central with I^2 = -1, so complex spans agree).
(1) GA: of the 45 bivectors e_p e_q, 6 + 15 = 21 have both indices in one block and 24 mix; the 21 close
    under the commutator (every commutator is a combination of block bivectors), the 24 do not (a mixed
    commutator of two mixed bivectors leaves the 24). Fock: the Clifford relations of the ten.
(2) Fock: su(2)_L = {v_4 w_5, v_5 w_4, (N_4 - N_5)/2} and su(2)_R = {v_4 v_5, w_5 w_4, (N_4 + N_5 - 1)/2}
    satisfy the su(2) relations, commute with each other and lie in (and with 1 span) the slot
    bilinears plus 1; su(3) (traceless pair mixings) and B - L = 1 - (2/3) N_W lie in the pair
    bilinears plus 1, which have dimension 15; Y = (3 N_R - 2 N_W)/6 equals T_3R + (B - L)/2 as matrices.
(3) Fock: on the sixteen (even total mode number) the commutant of the 21 is two-dimensional, spanned
    by 1 and chi = -(-1)^(N_R), which is +1 on the 8 slot-doublet states and -1 on the 8 others.
The group-level sentence (Spin(4) x Spin(6), and U(2) x U(3) when the mode number is kept) is the
Lie-algebra statement above integrated; it is not tested beyond the algebra.
"""
from fractions import Fraction as F

import GA
from pyutil import get_or_set
import fock
from tp_premise import premise

# ---------------------------------------------------------------------------
# The five-mode module Lambda(W + R_2) = Lambda(C^5), exact.
# States are bitmasks s in 0..31; mode m is occupied when bit m is set.
# Modes 0, 1, 2 are the three pair modes (W), modes 3, 4 the two slot (rung)
# modes, the text's modes 4 and 5. Operators are sparse matrices
# {(row, col): Fraction}; Jordan-Wigner sign (-1)^(occupied modes below m).
# ---------------------------------------------------------------------------
NM = 5
DIM = 32
PAIRS = (0, 1, 2)
SLOTS = (3, 4)


def nw(s):
    return sum(1 for m in PAIRS if s >> m & 1)


def nr(s):
    return sum(1 for m in SLOTS if s >> m & 1)


def ntot(s):
    return nw(s) + nr(s)


mm, madd, msc, msub = fock.mm, fock.madd, fock.msc, fock.msub
comm, acomm, meq, restrict = fock.comm, fock.acomm, fock.meq, fock.restrict


def diag(fn):
    return fock.diag(fn, DIM)


ONE = fock.eye(DIM)
V = [fock.cre(m, NM) for m in range(NM)]    # v_m, creation
W = [fock.ann(m, NM) for m in range(NM)]    # w_m, annihilation
NUM = [mm(V[m], W[m]) for m in range(NM)]   # n_m


def gam(p):
    """Majorana p = 0..9 of mode p // 2 in the real form: gamma_{2m} = v_m + w_m (square +1),
    g_{2m+1} = w_m - v_m (square -1). The text's gamma_{2m+1} = I g_{2m+1}, I^2 = -1 central."""
    return fock.majorana(p, NM)


class Span:
    """Incremental exact span of sparse vectors (dicts with hashable keys), reduced row echelon."""

    def __init__(self):
        self.piv, self.where = {}, {}

    def reduce(self, v):
        v = {k: x for k, x in v.items() if x}
        for k in [k for k in v if k in self.piv]:
            c = v.pop(k)
            for kk, xx in self.piv[k].items():
                if kk != k:
                    y = v.get(kk, 0) - c * xx
                    if y:
                        v[kk] = y
                    else:
                        v.pop(kk, None)
        return v

    def add(self, v):
        v = self.reduce(v)
        if not v:
            return False
        k0 = next(iter(v))
        c0 = v[k0]
        v = {k: x / c0 for k, x in v.items()}
        for p in list(self.where.get(k0, ())):
            row = self.piv[p]
            c = row.pop(k0)
            for kk, xx in v.items():
                if kk != k0:
                    y = row.get(kk, 0) - c * xx
                    if y:
                        row[kk] = y
                        get_or_set(self.where, kk, set()).add(p)
                    else:
                        row.pop(kk, None)
                        self.where.get(kk, set()).discard(p)
        self.where.pop(k0, None)
        self.piv[k0] = v
        for kk in v:
            if kk != k0:
                get_or_set(self.where, kk, set()).add(k0)
        return True

    def __len__(self):
        return len(self.piv)


def rank(vecs):
    """Exact rank of sparse vectors (dicts with hashable keys)."""
    sp = Span()
    for v in vecs:
        sp.add(v)
    return len(sp)


def in_span(vecs, v):
    sp = Span()
    for u in vecs:
        sp.add(u)
    return not sp.reduce(v)


def bilinears():
    """The 45 products g_p g_q, p < q, of the real-form Majoranas (the bivectors of the ten,
    up to the central factors of I)."""
    G = [gam(p) for p in range(2 * NM)]
    return {(p, q): mm(G[p], G[q]) for p in range(2 * NM) for q in range(p + 1, 2 * NM)}


def commutant_dim(gens, states):
    """Dimension of {X on span(states) : [X, g] = 0 for all g}, by exact sparse elimination."""
    S = list(states)
    Sset = set(S)
    rows = []
    for g in gens:
        g = restrict(g, S)
        grow, gcol = {}, {}
        for (r, c), x in g.items():
            get_or_set(grow, r, []).append((c, x))
            get_or_set(gcol, c, []).append((r, x))
        for r in S:
            for c in S:
                eq = {}
                # (X g)_{rc} = sum_k X_{rk} g_{kc};  (g X)_{rc} = sum_k g_{rk} X_{kc}
                for k, x in gcol.get(c, ()):
                    eq[(r, k)] = eq.get((r, k), 0) + x
                for k, x in grow.get(r, ()):
                    eq[(k, c)] = eq.get((k, c), 0) - x
                eq = {k: x for k, x in eq.items() if x}
                if eq:
                    rows.append(eq)
    return len(S) * len(S) - rank(rows)

S10 = GA.sig(10, 0)
PAIR_G = tuple(range(6))
SLOT_G = (6, 7, 8, 9)


def gbiv(p, q):
    return GA.mul(GA.gen(p), GA.gen(q), S10)


def same_block(p, q):
    return (p in SLOT_G) == (q in SLOT_G)


def blade_ok(blade, allowed):
    return len(blade) == 2 and allowed(blade[0], blade[1])


def T3R():
    return msc(F(1, 2), madd(NUM[3], NUM[4], msc(-1, ONE)))


def T3L():
    return msc(F(1, 2), msub(NUM[3], NUM[4]))


def BL():
    return diag(lambda s: 1 - F(2, 3) * nw(s))


def HYP():
    return diag(lambda s: F(3 * nr(s) - 2 * nw(s), 6))


def check_split_bivectors_close():
    premise("standard-model.imported-fock-representation-clifford-algebra-bogoliubov")
    pairs = [(p, q) for p in range(10) for q in range(p + 1, 10)]
    split = [pq for pq in pairs if same_block(*pq)]
    mixed = [pq for pq in pairs if not same_block(*pq)]
    ok = len(pairs) == 45 and len(split) == 21 and len(mixed) == 24
    ok = ok and sum(1 for p, q in split if p in SLOT_G) == 6 and sum(1 for p, q in split if p in PAIR_G) == 15
    closed = True
    for a in split:
        for b in split:
            c = GA.sub(GA.mul(gbiv(*a), gbiv(*b), S10), GA.mul(gbiv(*b), gbiv(*a), S10))
            closed = closed and all(blade_ok(bl, same_block) for bl in c)
    ok = ok and closed
    # the mixed ones do not close: [e0 e6, e1 e6] = -2 e0 e1 is a block bivector
    c = GA.sub(GA.mul(gbiv(0, 6), gbiv(1, 6), S10), GA.mul(gbiv(1, 6), gbiv(0, 6), S10))
    ok = ok and GA.eq(c, GA.scal(F(-2), gbiv(0, 1)))
    # Fock: the ten Majoranas satisfy the Clifford relations (signature (5,5) in the real form)
    G = [gam(p) for p in range(10)]
    for p in range(10):
        for q in range(10):
            want = {} if p != q else msc(2 * (-1) ** p, ONE)
            ok = ok and meq(acomm(G[p], G[q]), want)
    ok = ok and rank(list(bilinears().values())) == 45
    GA.check("the 21 split-preserving bivectors (6 + 15) close; the 45 are independent", ok)
    return ok


def check_left_right_and_pati_salam_generators():
    premise("standard-model.imported-pati-salam-representation-theory-survival")
    premise("standard-model.under-s-composites-state-space-spinor")
    premise("standard-model.hyp-s-slot-statistics")
    Bl = bilinears()
    slot_b = [X for (p, q), X in Bl.items() if p in SLOT_G and q in SLOT_G]
    pair_b = [X for (p, q), X in Bl.items() if p in PAIR_G and q in PAIR_G]
    ok = len(slot_b) == 6 and len(pair_b) == 15 and rank(slot_b) == 6 and rank(pair_b) == 15
    L = [mm(V[3], W[4]), mm(V[4], W[3]), T3L()]
    R = [mm(V[3], V[4]), mm(W[4], W[3]), T3R()]
    for (tp, tm, t3) in (L, R):
        ok = ok and meq(comm(tp, tm), msc(2, t3))
        ok = ok and meq(comm(t3, tp), tp) and meq(comm(t3, tm), msc(-1, tm))
    ok = ok and all(not comm(x, y) for x in L for y in R)
    # inside slot bilinears + 1, and together with 1 they span it
    ok = ok and rank(slot_b + [ONE]) == 7 and rank(slot_b + [ONE] + L + R) == 7 and rank(L + R + [ONE]) == 7
    su3 = [mm(V[a], W[b]) for a in PAIRS for b in PAIRS if a != b]
    su3 += [msub(NUM[0], NUM[1]), msub(NUM[1], NUM[2])]
    ok = ok and len(su3) == 8 and rank(su3) == 8
    ok = ok and rank(pair_b + [ONE]) == 16 and rank(pair_b + [ONE] + su3 + [BL()]) == 16
    ok = ok and rank(su3 + [BL(), ONE]) == 10
    # Y = T_3R + (B - L)/2 exactly
    ok = ok and meq(HYP(), madd(T3R(), msc(F(1, 2), BL())))
    # the 24 mixed bilinears all move an excitation between a slot and a pair mode
    mixed = [X for (p, q), X in Bl.items() if (p in SLOT_G) != (q in SLOT_G)]
    NR = madd(NUM[3], NUM[4])
    ok = ok and len(mixed) == 24 and all(comm(NR, X) for X in mixed)
    GA.check("su(2)_L + su(2)_R in the slot bivectors, su(3) and B - L in the pair ones, Y = T3R + (B-L)/2", ok)
    return ok


def check_commutant_on_sixteen():
    premise("standard-model.hyp-s-slot-statistics")
    Bl = bilinears()
    gens = [X for (p, q), X in Bl.items() if same_block(p, q)]
    sixteen = [s for s in range(DIM) if ntot(s) % 2 == 0]
    ok = len(gens) == 21 and len(sixteen) == 16
    ok = ok and commutant_dim(gens, sixteen) == 2
    chi = diag(lambda s: -(-1) ** nr(s))
    chi16 = restrict(chi, sixteen)
    ok = ok and all(not comm(restrict(X, sixteen), chi16) for X in gens)
    ok = ok and sum(1 for s in sixteen if nr(s) == 1) == 8
    ok = ok and all(chi[(s, s)] == (1 if nr(s) == 1 else -1) for s in sixteen)
    GA.check("on the sixteen the commutant of the 21 is spanned by 1 and chi", ok)
    return ok

standard-model.bidoublet-complex:
"""standard-model.bidoublet-complex: exact checks.

The five-mode module as 32 x 32 matrices over Q(i) (GA.QI), pair modes 0, 1, 2 and slot (rung) modes 3, 4,
the text's v_4, w_4 being v_3, w_3 here. As in the proof, the imaginary unit is I (central), gamma_6 = v_4 + w_4
and gamma_7 = I (v_4 - w_4).
(1) The lemma: for real sample (x, y), including the proof's (3, 5), x gamma_6 + y gamma_7 = a v_4 + b w_4 with
    a = x + I y read off the matrix, b = conj(a), |a|^2 = |b|^2 = x^2 + y^2. Conversely a v_4 + b w_4 lies in
    the real span of gamma_6, gamma_7 exactly when b = conj(a) (solved: x = (a + b)/2, y = (a - b)/(2I) real).
(2) The mass form M_c(psi, phi) = B(psi, c phi) on the sixteen (B the invariant pairing of the five modes,
    built from its formula) has its nonzero entries on (L, nu^c), (Q, u^c) with magnitude |a| and on
    (L, e^c), (Q, d^c) with magnitude |b| (the Corollary's entries).
(3) One rung vector, under the c* reading of the one-vev Corollary (up-type masses are the entries of M_{c*}
    on (Q, u^c), (L, nu^c), with c* = conj(b) v_4 + conj(a) w_4; down-type the entries of M_c on (Q, d^c),
    (L, e^c)): for real and complex samples the up-type and down-type magnitudes are equal (both |b|), so
    m_u = m_d at tree level whether the vector is real or complex; control: read through c itself the
    complex samples would separate them.
(4) Two independent couplings, down-type through c_1 and up-type through c_2*: the magnitudes are |b_1| and
    |b_2|, unequal at the samples (ratios of squares 25 and 1/2), so a second doublet coupling separates
    m_u from m_d.
"""
from fractions import Fraction as F

import GA
from pyutil import get_or_set
import fock
from tp_premise import premise

# ---------------------------------------------------------------------------
# The five-mode module Lambda(W + R_2) = Lambda(C^5), exact.
# States are bitmasks s in 0..31; mode m is occupied when bit m is set.
# Modes 0, 1, 2 are the three pair modes (W), modes 3, 4 the two slot (rung)
# modes, the text's modes 4 and 5. Operators are sparse matrices
# {(row, col): Fraction}; Jordan-Wigner sign (-1)^(occupied modes below m).
# ---------------------------------------------------------------------------
NM = 5
DIM = 32
PAIRS = (0, 1, 2)
SLOTS = (3, 4)


def nw(s):
    return sum(1 for m in PAIRS if s >> m & 1)


def nr(s):
    return sum(1 for m in SLOTS if s >> m & 1)


def ntot(s):
    return nw(s) + nr(s)


mm, madd, msc, msub = fock.mm, fock.madd, fock.msc, fock.msub
meq, restrict = fock.meq, fock.restrict


def gam(p):
    """Majorana p = 0..9 of mode p // 2 in the real form: gamma_{2m} = v_m + w_m (square +1),
    g_{2m+1} = w_m - v_m (square -1). The text's gamma_{2m+1} = I g_{2m+1}, I^2 = -1 central."""
    return fock.majorana(p, NM)


ONE = fock.eye(DIM)
V = [fock.cre(m, NM) for m in range(NM)]  # v_m, creation
W = [fock.ann(m, NM) for m in range(NM)]  # w_m, annihilation
NUM = [fock.num(m, NM) for m in range(NM)]  # n_m


class Span:
    """Incremental exact span of sparse vectors (dicts with hashable keys), reduced row echelon."""

    def __init__(self):
        self.piv, self.where = {}, {}

    def reduce(self, v):
        v = {k: x for k, x in v.items() if x}
        for k in [k for k in v if k in self.piv]:
            c = v.pop(k)
            for kk, xx in self.piv[k].items():
                if kk != k:
                    y = v.get(kk, 0) - c * xx
                    if y:
                        v[kk] = y
                    else:
                        v.pop(kk, None)
        return v

    def add(self, v):
        v = self.reduce(v)
        if not v:
            return False
        k0 = next(iter(v))
        c0 = v[k0]
        v = {k: x / c0 for k, x in v.items()}
        for p in list(self.where.get(k0, ())):
            row = self.piv[p]
            c = row.pop(k0)
            for kk, xx in v.items():
                if kk != k0:
                    y = row.get(kk, 0) - c * xx
                    if y:
                        row[kk] = y
                        get_or_set(self.where, kk, set()).add(p)
                    else:
                        row.pop(kk, None)
                        self.where.get(kk, set()).discard(p)
        self.where.pop(k0, None)
        self.piv[k0] = v
        for kk in v:
            if kk != k0:
                get_or_set(self.where, kk, set()).add(k0)
        return True

    def __len__(self):
        return len(self.piv)


def rank(vecs):
    """Exact rank of sparse vectors (dicts with hashable keys)."""
    sp = Span()
    for v in vecs:
        sp.add(v)
    return len(sp)


def in_span(vecs, v):
    sp = Span()
    for u in vecs:
        sp.add(u)
    return not sp.reduce(v)


def bilinears():
    """The 45 products g_p g_q, p < q, of the real-form Majoranas (the bivectors of the ten,
    up to the central factors of I)."""
    G = [gam(p) for p in range(2 * NM)]
    return {(p, q): mm(G[p], G[q]) for p in range(2 * NM) for q in range(p + 1, 2 * NM)}


def commutant_dim(gens, states):
    """Dimension of {X on span(states) : [X, g] = 0 for all g}, by exact sparse elimination."""
    S = list(states)
    Sset = set(S)
    rows = []
    for g in gens:
        g = restrict(g, S)
        grow, gcol = {}, {}
        for (r, c), x in g.items():
            get_or_set(grow, r, []).append((c, x))
            get_or_set(gcol, c, []).append((r, x))
        for r in S:
            for c in S:
                eq = {}
                # (X g)_{rc} = sum_k X_{rk} g_{kc};  (g X)_{rc} = sum_k g_{rk} X_{kc}
                for k, x in gcol.get(c, ()):
                    eq[(r, k)] = eq.get((r, k), 0) + x
                for k, x in grow.get(r, ()):
                    eq[(k, c)] = eq.get((k, c), 0) - x
                eq = {k: x for k, x in eq.items() if x}
                if eq:
                    rows.append(eq)
    return len(S) * len(S) - rank(rows)

QI = GA.QI
I = GA.QI_I
SAMPLES = [(F(3), F(5)), (F(-2), F(7, 3)), (F(1, 2), F(-4)), (F(6), F(0))]
MASS_FORM_AB = ((QI(3, 5), QI(3, -5)), (QI(3), QI(1)))   # sample (a, b): the proof's real (3, 5) and a complex pair
SPECIES = {(0, 0): "nuc", (2, 0): "uc", (1, 1): "Q", (3, 1): "L", (0, 2): "ec", (2, 2): "dc"}


def species(s):
    return SPECIES.get((nw(s), nr(s)))


def pairing():
    B = {}
    for s in range(DIM):
        S = [m for m in range(NM) if s >> m & 1]
        seq = S + [m for m in range(NM) if not s >> m & 1]
        inv = sum(1 for i in range(NM) for j in range(i + 1, NM) if seq[i] > seq[j])
        k = len(S)
        B[(s, (DIM - 1) ^ s)] = F((-1) ** (k * (k - 1) // 2 + inv))
    return B


def rung_vector(x, y):
    g6 = madd(V[3], W[3])
    g7 = msc(I, msub(V[3], W[3]))
    return madd(msc(QI(x), g6), msc(QI(y), g7))


def norm2(z):
    z = QI(z)
    return (z * z.conj()).re


def check_real_rung_vector_has_conjugate_coefficients():
    premise("standard-model.hyp-s-slot-statistics")
    ok = True
    for x, y in SAMPLES:
        c = rung_vector(x, y)
        a, b = c[(8, 0)], c[(0, 8)]
        ok = ok and meq(c, madd(msc(a, V[3]), msc(b, W[3])))
        ok = ok and b == a.conj() and norm2(a) == norm2(b) == x * x + y * y
    ok = ok and rung_vector(F(3), F(5))[(8, 0)] == QI(3, 5)
    # converse: a v + b w is real (x, y real) iff b = conj(a)
    for a, b, real in ((QI(2, 1), QI(2, -1), True), (QI(1), QI(0), False), (QI(0, 3), QI(0, 3), False)):
        x, y = (a + b) / 2, (a - b) / (2 * I)
        ok = ok and ((x.im == 0 and y.im == 0) == real) and ((b == a.conj()) == real)
    GA.check("a real vector of the rung plane is a v4 + conj(a) w4", ok)
    return ok


def check_mass_form_magnitudes():
    premise("standard-model.one-vev-vector-relations-breaking-pattern")
    premise("standard-model.hyp-s-slot-statistics")
    B = pairing()
    sixteen = [s for s in range(DIM) if ntot(s) % 2 == 0]
    ok = True
    for a, b in MASS_FORM_AB:
        c = rung(a, b)                       # a v_4 + b w_4
        M = mm(B, c)
        mags = {}
        for (r, col), z in M.items():
            if r in sixteen and col in sixteen:
                pair = tuple(sorted((species(r), species(col))))
                if pair not in mags:
                    mags[pair] = set()
                mags[pair].add(norm2(z))
        want = {("L", "nuc"): {norm2(a)}, ("Q", "uc"): {norm2(a)},
                ("L", "ec"): {norm2(b)}, ("Q", "dc"): {norm2(b)}}
        ok = ok and mags == want
    GA.check("the mass form has |a| on (L, nu^c), (Q, u^c) and |b| on (L, e^c), (Q, d^c)", ok)
    return ok


def rung(a, b):
    return madd(msc(QI(a), V[3]), msc(QI(b), W[3]))


def entry_mags(c):
    """|entry|^2 of M_c on the sixteen, by species pair."""
    B = pairing()
    sixteen = {s for s in range(DIM) if ntot(s) % 2 == 0}
    mags = {}
    for (r, col), z in mm(B, c).items():
        if r in sixteen and col in sixteen:
            get_or_set(mags, tuple(sorted((species(r), species(col)))), set()).add(norm2(z))
    return mags


# one rung vector (a, b): real ones (b = conj(a)) and complex ones (a, b independent, |a| != |b|)
ONE_REAL = [(QI(3, 5), QI(3, -5)), (QI(F(-2), F(7, 3)), QI(F(-2), F(-7, 3)))]
ONE_COMPLEX = [(QI(3), QI(1)), (QI(2, -1), QI(0, 4)), (QI(1, 2), QI(F(-1, 2), 1))]
# two couplings: ((a_1, b_1) for the down-type vector c_1, (a_2, b_2) for the up-type vector c_2)
TWO = [((QI(2, 1), QI(1)), (QI(0, 1), QI(3, 4))), ((QI(1, -1), QI(0, 2)), (QI(5), QI(1, 1)))]


def check_one_rung_vector_gives_equal_up_and_down_masses():
    premise("standard-model.one-vev-vector-relations-breaking-pattern")
    premise("standard-model.hyp-s-slot-statistics")
    ok = True
    for real, samples in ((True, ONE_REAL), (False, ONE_COMPLEX)):
        for a, b in samples:
            ok = ok and (b == a.conj()) == real
            c = rung(a, b)
            cstar = rung(b.conj(), a.conj())
            up, down = entry_mags(cstar), entry_mags(c)
            m = {norm2(b)}
            ok = ok and up[("Q", "uc")] == m and up[("L", "nuc")] == m
            ok = ok and down[("Q", "dc")] == m and down[("L", "ec")] == m
            # control: read through c itself, the up-type entry is |a|, which separates the complex samples
            ok = ok and (down[("Q", "uc")] == down[("Q", "dc")]) == real
    GA.check("one rung vector, real or complex: through c*, m_u = m_d = |b| at tree level", ok)
    return ok


def check_two_couplings_separate_up_and_down():
    premise("standard-model.one-vev-vector-relations-breaking-pattern")
    premise("standard-model.hyp-s-slot-statistics")
    ok = True
    ratios = []
    for (a1, b1), (a2, b2) in TWO:
        down = entry_mags(rung(a1, b1))[("Q", "dc")]
        up = entry_mags(rung(b2.conj(), a2.conj()))[("Q", "uc")]
        ok = ok and down == {norm2(b1)} and up == {norm2(b2)} and up != down
        ratios.append(next(iter(up)) / next(iter(down)))
    ok = ok and ratios == [F(25), F(1, 2)]
    GA.check("two independent doublet couplings: m_u = |b_2| and m_d = |b_1|, unequal", ok)
    return ok

standard-model.bracket-composite-lands:
"""standard-model.bracket-composite-lands: exact checks.

Model: the five-mode module (pair modes 0, 1, 2; rung modes 3, 4, the text's 4 and 5), v_i creation, w_i
annihilation, as exact sparse matrices; Y = N_R/2 - N_W/3, T3 = (N_4 - N_5)/2; the frozen point
I = a v_1 + b w_1 (a = 2, b = 3), lifted rung components c_4 = -w_4 + lam v_4 (lam = 1/7), c_5 = -w_5, the
bracket b = v_4 v_5 and b^dag = w_5 w_4. Mass forms: f(X)(psi, phi) = B(psi, X phi) on the sixteen even states,
B the top-degree pairing with the reversal sign, symmetrised; species by (rung, pair) occupation.
(i) The algebra generated by I, c_4, c_5, b, b^dag (closed under products from 1) has dimension 32; the sixteen
    ordered monomials in v_4, w_4, v_5, w_5 span Cl_R (dimension 16); Cl_R and I Cl_R together span the
    algebra and meet only in zero (16 + 16 = 32).
(ii) The commutant of su(3) (the six v_i w_j, i != j pairs) inside the algebra has dimension 16 and is Cl_R.
(iii) The odd monomials of Cl_R with ad-weights Y = -1/2 and T3 = -1/2 span a two-dimensional space, spanned by
    w_4 and w_4 N_5.
(iv) f(w_4 N_5) = (1/2) f(w_4); f(w_4) couples only (L, e^c) and (Q, d^c), with equal magnitudes 1 (the 10
    form, |y_e| = |y_d|); b^dag v_5 = -w_4 + w_4 N_5 and its form is -(1/2) f(w_4).
(v) T_GJ = w_4 (B - L) chi (B - L = 1 - (2/3) N_W, chi = -(-1)^{N_R}) has a form outside the span of the
    forms of w_4 and w_4 N_5 (rank 1 -> 2); the pair bivector sum_i v_i ^ w_i is not in the algebra
    (rank 32 -> 33).
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from pyutil import get_or_set
from tp_premise import premise

# ---------------------------------------------------------------------------
# The five-mode module Lambda(W + R_2) = Lambda(C^5), exact (sparse matrices {(row, col): Fraction}).
# Modes 0, 1, 2 are the pair modes (W), modes 3, 4 the two rung (slot) modes, the text's modes 4 and 5.
# v_i = creation (wedge), w_i = annihilation (contraction), v_i w_i + w_i v_i = 1.
# ---------------------------------------------------------------------------
NM = 5
PAIRS5, RUNGS5 = (0, 1, 2), (3, 4)
STATES = [frozenset(S) for k in range(NM + 1) for S in combinations(range(NM), k)]
SIDX = {S: i for i, S in enumerate(STATES)}
DIM5 = len(STATES)


def sp_from_action(act):
    M = {}
    for S in STATES:
        for T, c in act(S).items():
            if c != 0:
                M[(SIDX[T], SIDX[S])] = M.get((SIDX[T], SIDX[S]), F(0)) + c
    return {k: v for k, v in M.items() if v != 0}


def sp_mul(A, B):
    Bc = {}
    for (i, j), b in B.items():
        get_or_set(Bc, i, []).append((j, b))
    C = {}
    for (i, k), a in A.items():
        for j, b in Bc.get(k, ()):
            C[(i, j)] = C.get((i, j), F(0)) + a * b
    return {k: v for k, v in C.items() if v != 0}


def sp_add(*Ms):
    C = {}
    for M in Ms:
        for k, v in M.items():
            C[k] = C.get(k, F(0)) + v
    return {k: v for k, v in C.items() if v != 0}


def sp_scal(c, M):
    return {k: c * v for k, v in M.items() if c * v != 0}


def sp_eq(A, B):
    return sp_add(A, sp_scal(F(-1), B)) == {}


def sp_apply(M, vec):
    out = {}
    for (i, j), a in M.items():
        if j in vec:
            out[i] = out.get(i, F(0)) + a * vec[j]
    return {k: v for k, v in out.items() if v != 0}


ID5 = {(i, i): F(1) for i in range(DIM5)}
V5 = [sp_from_action(lambda S, i=i: GA.ext_wedge(i, {S: F(1)})) for i in range(NM)]
W5 = [sp_from_action(lambda S, i=i: GA.ext_contract([F(1) if j == i else F(0) for j in range(NM)], {S: F(1)}))
      for i in range(NM)]


def num(i):
    return sp_mul(V5[i], W5[i])


RUNG4, RUNG5 = 3, 4                          # the text's rung modes 4 and 5 are modes 3 and 4 here


N_W = sp_add(*[num(i) for i in PAIRS5])
N_R = sp_add(*[num(i) for i in RUNGS5])
HYP = sp_add(sp_scal(F(1, 2), N_R), sp_scal(F(-1, 3), N_W))
T3 = sp_scal(F(1, 2), sp_add(num(3), sp_scal(F(-1), num(4))))
SU3 = [sp_mul(V5[i], W5[j]) for i in PAIRS5 for j in PAIRS5 if i != j]
SU2 = [sp_mul(V5[3], W5[4]), sp_mul(V5[4], W5[3]), T3]


def comm(A, B):
    return sp_add(sp_mul(A, B), sp_scal(F(-1), sp_mul(B, A)))


def weight(M, Q):
    """The eigenvalue of ad Q on M, or None if M is not an eigenvector."""
    c = comm(Q, M)
    if c == {}:
        return F(0)
    (i, j), a = next(iter(M.items()))
    q = c.get((i, j), F(0)) / a
    return q if sp_eq(c, sp_scal(q, M)) else None


def basis5(S):
    return {SIDX[frozenset(S)]: F(1)}

A_, B_, LAM = F(2), F(3), F(1, 7)
SIXTEEN = [S for S in STATES if len(S) % 2 == 0]
FULL5 = frozenset(range(NM))


def species(S):
    nr, nw = len(S & set(RUNGS5)), len(S & set(PAIRS5))
    return {(0, 0): "nu^c", (2, 0): "e^c", (1, 1): "Q", (1, 3): "L", (0, 2): "u^c", (2, 2): "d^c"}.get((nr, nw), "odd")


def eps_sign5(S):
    seq = sorted(S) + sorted(FULL5 - S)
    return F(-1) ** sum(1 for a in range(len(seq)) for b in range(a + 1, len(seq)) if seq[a] > seq[b])


BCOEF5 = {S: F(-1) ** (len(S) * (len(S) - 1) // 2) * eps_sign5(S) for S in STATES}


def bpair5(psi, phi):
    return sum((BCOEF5[S] * psi.get(SIDX[S], F(0)) * phi.get(SIDX[FULL5 - S], F(0)) for S in STATES), F(0))


def yukawa(T):
    mat = {}
    for S in SIXTEEN:
        for U in SIXTEEN:
            val = bpair5(basis5(S), sp_apply(T, basis5(U)))
            if val != 0:
                mat[(S, U)] = val
    return mat


def sym(mat):
    keys = set(mat) | {(b, a) for a, b in mat}
    out = {k: F(1, 2) * (mat.get(k, F(0)) + mat.get((k[1], k[0]), F(0))) for k in keys}
    return {k: v for k, v in out.items() if v != 0}


def species_blocks(f):
    out = {}
    for (S, U), v in f.items():
        get_or_set(out, tuple(sorted((species(S), species(U)))), set()).add(abs(v))
    return out


class Span:
    """Incremental row echelon over sparse dict vectors."""

    def __init__(self):
        self.rows = []

    def reduce(self, x):
        x = dict(x)
        for piv, row in self.rows:
            c = x.get(piv)
            if c:
                for k, v in row.items():
                    x[k] = x.get(k, F(0)) - c * v
                x = {k: v for k, v in x.items() if v != 0}
        return x

    def add(self, x):
        r = self.reduce(x)
        if not r:
            return False
        piv = min(r)
        c = r[piv]
        self.rows.append((piv, {k: v / c for k, v in r.items()}))
        return True

    def __len__(self):
        return len(self.rows)


def rank_of(ops):
    s = Span()
    for M in ops:
        s.add(M)
    return len(s)


def generators():
    Iop = sp_add(sp_scal(A_, V5[0]), sp_scal(B_, W5[0]))
    c4 = sp_add(sp_scal(F(-1), W5[3]), sp_scal(LAM, V5[3]))
    c5 = sp_scal(F(-1), W5[4])
    brk = sp_mul(V5[3], V5[4])
    brk_d = sp_mul(W5[4], W5[3])
    return Iop, [Iop, c4, c5, brk, brk_d]


def algebra_basis(gens):
    s = Span()
    s.add(ID5)
    basis = [ID5]
    frontier = [ID5]
    while frontier:
        new = []
        for x in frontier:
            for g in gens:
                y = sp_mul(x, g)
                if s.add(y):
                    basis.append(y)
                    new.append(y)
        frontier = new
    return basis


def rung_monomials():
    ops = [V5[3], W5[3], V5[4], W5[4]]
    out = []
    for k in range(5):
        for idx in combinations(range(4), k):
            M = ID5
            for t in idx:
                M = sp_mul(M, ops[t])
            out.append(M)
    return out


def check_algebra_is_rung_clifford_plus_frozen_point_multiple():
    premise("standard-model.hyp-s-slot-statistics")
    ok = True
    Iop, gens = generators()
    basis = algebra_basis(gens)
    ok = ok and len(basis) == 32
    clr = rung_monomials()
    ok = ok and rank_of(clr) == 16
    iclr = [sp_mul(Iop, X) for X in clr]
    ok = ok and rank_of(clr + iclr) == 32 and rank_of(basis + clr + iclr) == 32
    ok = ok and sp_eq(sp_mul(Iop, Iop), sp_scal(A_ * B_, ID5))
    _tp_rv = (ok); assert _tp_rv is not False, "check_algebra_is_rung_clifford_plus_frozen_point_multiple"; return _tp_rv


def check_colour_singlet_part_is_rung_clifford():
    premise("standard-model.hyp-s-slot-statistics")
    ok = True
    _, gens = generators()
    basis = algebra_basis(gens)
    keys = sorted({k for X in SU3 for M in basis for k in comm(X, M)})
    comms = [[comm(X, M) for M in basis] for X in SU3]
    rows = [[c.get(k, F(0)) for c in cs] for cs in comms for k in keys]
    # keep an independent set of rows (the kernel only depends on their span)
    s = Span()
    rows = [r for r in rows if s.add({i: v for i, v in enumerate(r) if v != 0})]
    ker = GA.field_kernel(rows)
    ok = ok and len(ker) == 16
    inv = [sp_add(*[sp_scal(c, M) for c, M in zip(v, basis) if c != 0]) for v in ker]
    clr = rung_monomials()
    ok = ok and rank_of(inv + clr) == 16
    _tp_rv = (ok); assert _tp_rv is not False, "check_colour_singlet_part_is_rung_clifford"; return _tp_rv


def check_doublet_direction_and_mass_forms():
    premise("standard-model.hyp-s-slot-statistics")
    ok = True
    parity = ID5
    for i in range(NM):
        parity = sp_mul(parity, sp_add(ID5, sp_scal(F(-2), num(i))))
    odd = [M for M in rung_monomials() if M and sp_add(sp_mul(parity, M), sp_mul(M, parity)) == {}]
    doublet = [M for M in odd if weight(M, HYP) == F(-1, 2) and weight(M, T3) == F(-1, 2)]
    w4 = W5[3]
    w4N5 = sp_mul(w4, num(4))
    ok = ok and rank_of(doublet) == 2 and rank_of(doublet + [w4, w4N5]) == 2
    f10, fN5 = sym(yukawa(w4)), sym(yukawa(w4N5))
    ok = ok and fN5 == {k: F(1, 2) * v for k, v in f10.items()}
    ok = ok and species_blocks(f10) == {("L", "e^c"): {F(1)}, ("Q", "d^c"): {F(1)}}
    comp = sp_mul(sp_mul(W5[4], W5[3]), V5[4])
    ok = ok and sp_eq(comp, sp_add(sp_scal(F(-1), w4), w4N5))
    ok = ok and sym(yukawa(comp)) == {k: F(-1, 2) * v for k, v in f10.items()}
    _tp_rv = (ok); assert _tp_rv is not False, "check_doublet_direction_and_mass_forms"; return _tp_rv


def check_126_direction_and_pair_bivector_outside():
    premise("standard-model.hyp-s-slot-statistics")
    ok = True
    w4 = W5[RUNG4]
    w4N5 = sp_mul(w4, num(RUNG5))
    chi = sp_scal(F(-1), sp_mul(sp_add(ID5, sp_scal(F(-2), num(RUNG4))), sp_add(ID5, sp_scal(F(-2), num(RUNG5)))))
    BmL = sp_add(ID5, sp_scal(F(-2, 3), N_W))
    # chi = -(-1)^{N_R}: an involution, -1 on the rung vacuum, anticommuting with the rung mode w_4
    empty, full = SIDX[frozenset()], SIDX[FULL5]
    ok = ok and sp_eq(sp_mul(chi, chi), ID5) and chi.get((empty, empty)) == -1
    ok = ok and sp_eq(sp_add(sp_mul(chi, w4), sp_mul(w4, chi)), {})
    # B - L = 1 - (2/3) N_W by hand: 1 with no pair mode occupied, 1 - 2 = -1 with all three occupied
    ok = ok and BmL.get((empty, empty)) == 1 and BmL.get((full, full)) == -1
    TGJ = sp_mul(w4, sp_mul(BmL, chi))
    forms = [sym(yukawa(w4)), sym(yukawa(w4N5)), sym(yukawa(TGJ))]
    keys = sorted({k for f in forms for k in f}, key=lambda k: tuple(sorted(x) for x in k))
    vecs = [[f.get(k, F()) for k in keys] for f in forms]
    ok = ok and GA.rank_of_vectors(vecs[:2]) == 1 and GA.rank_of_vectors(vecs) == 2
    _, gens = generators()
    basis = algebra_basis(gens)
    pairbiv = sp_add(*[sp_scal(F(1, 2), sp_add(sp_mul(V5[i], W5[i]), sp_scal(F(-1), sp_mul(W5[i], V5[i]))))
                       for i in PAIRS5])
    # by hand: v_i w_i - w_i v_i = 2 N_i - 1, so the pair bivector is N_W - 3/2
    ok = ok and sp_eq(pairbiv, sp_add(N_W, sp_scal(F(-3, 2), ID5)))
    ok = ok and rank_of(basis + [pairbiv]) == 33
    _tp_rv = (ok); assert _tp_rv is not False, "check_126_direction_and_pair_bivector_outside"; return _tp_rv

standard-model.family-no-go-vev-cannot-s:
"""standard-model.family-no-go-vev-cannot-separate: exact checks.

The five-mode module as 32 x 32 rational matrices with the invariant pairing B (the same construction as
families.doublet-direction-module-georgi-jarlskog-clebsch, rebuilt here because that claim is not a premise),
species named by Hypothesis (S); Y_x(psi, phi) = B(psi, x phi) on the sixteen.
(1) One-family Clebsches. For each of the four rung mode vectors w_4, w_5 (Y = -1/2) and v_4, v_5 (Y = +1/2),
    and for the doublet combinations a w_4 + b w_5, a v_4 + b v_5 at sample rational (a, b), the form is
    symmetric, couples only (L, e^c), (Q, d^c) (Y = -1/2) or (L, nu^c), (Q, u^c) (Y = +1/2), and the set of
    entry magnitudes on the lepton pair equals that on the quark pair, {|a|, |b|} with |a|, |b| read off the
    coefficients: |y_e| = |y_d| and |y_nu| = |y_u|.
(2) Family factor. For a non-symmetric invertible rational F and every signed entry pair (y_e, y_d) of the
    10 form, the characteristic polynomials of y_e F and y_d F agree coefficientwise up to the signs (-1)^k
    (roots negated), and M M^T has the same characteristic polynomial (equal singular spectra). Control: the
    126 entries (y_e, y_d) = (-1, +-1/3) of T_GJ = w_4 (B - L) chi give different spectra, so the test
    discriminates. Up-type: the same with x = v_4.
EXPORTS["module"] passes the module construction on (no premise call inside it).
"""
from fractions import Fraction as F

import GA
from pyutil import get_or_set
import fock
from tp_premise import premise

# sample rung-plane coefficients and a generic family matrix (inputs, not asserted values)
SAMPLES = [(F(1), F(0)), (F(0), F(1)), (F(2), F(-3)), (F(5, 7), F(1, 2))]
FAM = [[F(2), F(1, 3), F(-1)], [F(0), F(5, 7), F(4)], [F(-1), F(3), F(1, 2)]]

# ---------------------------------------------------------------------------
# module construction (generic; nothing here is asserted)
# ---------------------------------------------------------------------------
NM = 5
DIM = 32
PAIRS = (0, 1, 2)
SLOTS = (3, 4)
SPECIES = {(0, 0): "nuc", (2, 0): "uc", (1, 1): "Q", (3, 1): "L", (0, 2): "ec", (2, 2): "dc"}  # (N_W, N_R)


def nw(s):
    return sum(1 for m in PAIRS if s >> m & 1)


def nr(s):
    return sum(1 for m in SLOTS if s >> m & 1)


def ntot(s):
    return nw(s) + nr(s)


def species(s):
    return SPECIES.get((nw(s), nr(s)))


mm, madd, msc, msub = fock.mm, fock.madd, fock.msc, fock.msub
comm, acomm, meq = fock.comm, fock.acomm, fock.meq
tr = fock.transpose   # the transpose (fock.trace is the trace); kept for EXPORTS["module"]


def create(m):
    return fock.cre(m, NM)


def diag(fn):
    return fock.diag(fn, DIM)


ONE = fock.eye(DIM)
V = [fock.cre(m, NM) for m in range(NM)]
W = [fock.ann(m, NM) for m in range(NM)]
NUM = [fock.num(m, NM) for m in range(NM)]
SIXTEEN = [s for s in range(DIM) if ntot(s) % 2 == 0]


def complement(s):
    return (DIM - 1) ^ s


def eps_sign(s):
    seq = [m for m in range(NM) if s >> m & 1] + [m for m in range(NM) if not s >> m & 1]
    return (-1) ** sum(1 for i in range(NM) for j in range(i + 1, NM) if seq[i] > seq[j])


def bcoef(s):
    k = bin(s).count("1")
    return F((-1) ** (k * (k - 1) // 2) * eps_sign(s))


def form(T):
    """Y_T(e_s, e_t) = B(e_s, T e_t) for s, t in the sixteen."""
    out = {}
    for s in SIXTEEN:
        for t in SIXTEEN:
            x = T.get((complement(s), t))
            if x:
                out[(s, t)] = bcoef(s) * x
    return out


def ftr(f):
    return {(t, s): x for (s, t), x in f.items()}


def fadd(*fs):
    return madd(*fs)


def sym(f):
    return msc(F(1, 2), madd(f, ftr(f)))


def clebsch(f):
    out = {}
    for (s, t), x in f.items():
        get_or_set(out, tuple(sorted((species(s), species(t)))), set()).add(x)
    return out


def op_weight(H, X):
    """c with [H, X] = c X, or None."""
    Y = comm(H, X)
    k = next(iter(X))
    c = Y.get(k, 0) / X[k]
    return c if meq(Y, msc(c, X)) else None


BL = diag(lambda s: 1 - F(2, 3) * nw(s))
CHI = diag(lambda s: -(-1) ** nr(s))
NW = diag(nw)
HYP = diag(lambda s: F(nr(s), 2) - F(nw(s), 3))
T3 = msc(F(1, 2), msub(NUM[3], NUM[4]))
SU3 = [mm(V[a], W[b]) for a in PAIRS for b in PAIRS if a != b] + [msub(NUM[0], NUM[1]), msub(NUM[1], NUM[2])]

# Clifford algebra of the ten in GA, signature (+,-) per mode
SQ = tuple([1, -1] * NM)
EMAT = []
for _m in range(NM):
    EMAT += [madd(V[_m], W[_m]), msub(W[_m], V[_m])]


def gv(m):
    return {(2 * m,): F(1, 2), (2 * m + 1,): F(-1, 2)}


def gw(m):
    return {(2 * m,): F(1, 2), (2 * m + 1,): F(1, 2)}


def gmul(*xs):
    out = xs[0]
    for y in xs[1:]:
        out = GA.mul(out, y, SQ)
    return out


def gwedge2(a, b):
    return GA.scal(F(1, 2), GA.sub(gmul(a, b), gmul(b, a)))


def gnum(m):
    return gmul(gv(m), gw(m))


def grades(x):
    return sorted({len(b) for b in x})


def gpart(x, k):
    return {b: c for b, c in x.items() if len(b) == k}


def to_mat(x):
    out = {}
    for b, c in x.items():
        M = ONE
        for i in b:
            M = mm(M, EMAT[i])
        out = madd(out, msc(c, M))
    return out


def ga_BL():
    return GA.add(GA.sc(1), GA.scal(F(-2, 3), GA.add(*[gnum(i) for i in PAIRS])))


def ga_chi():
    return GA.neg(gmul(GA.sub(GA.sc(1), GA.scal(2, gnum(3))), GA.sub(GA.sc(1), GA.scal(2, gnum(4)))))


def ga_TGJ():
    return gmul(gw(3), ga_BL(), ga_chi())


def T_GJ():
    return mm(W[3], BL, CHI)


def T_GJ_up():
    return mm(V[3], BL, CHI)


def kernel(vecs):
    """Exact rank and kernel of a list of sparse vectors: returns (rank, [coefficient dicts c with sum c_i vecs_i = 0])."""
    piv, ker = [], []
    for i, v in enumerate(vecs):
        v = {k: x for k, x in v.items() if x}
        c = {i: F(1)}
        for key, pv, pc in piv:
            x = v.get(key)
            if x:
                v = madd(v, msc(-x, pv))
                c = madd(c, msc(-x, pc))
        if v:
            key = next(iter(v))
            x = v[key]
            piv.append((key, msc(1 / x, v), msc(1 / x, c)))
        else:
            ker.append(c)
    return len(piv), ker


def rank(vecs):
    return kernel(vecs)[0]


EXPORTS = {"module": {k: v for k, v in globals().items() if not k.startswith("_") and k not in ("GA", "fock", "F", "premise")}}


def charpoly3(M):
    """(trace, sum of principal 2-minors, det) of a 3 x 3 matrix: det(t - M) = t^3 - c1 t^2 + c2 t - c3."""
    t = M[0][0] + M[1][1] + M[2][2]
    m2 = sum(M[i][i] * M[j][j] - M[i][j] * M[j][i] for i, j in ((0, 1), (0, 2), (1, 2)))
    d = (M[0][0] * (M[1][1] * M[2][2] - M[1][2] * M[2][1])
         - M[0][1] * (M[1][0] * M[2][2] - M[1][2] * M[2][0])
         + M[0][2] * (M[1][0] * M[2][1] - M[1][1] * M[2][0]))
    return (t, m2, d)


def m3(A, B):
    return [[sum(A[i][k] * B[k][j] for k in range(3)) for j in range(3)] for i in range(3)]


def t3(A):
    return [[A[j][i] for j in range(3)] for i in range(3)]


def s3(c, A):
    return [[c * x for x in row] for row in A]


def magnitudes(f, pair):
    return {abs(x) for (s, t), x in f.items() if tuple(sorted((species(s), species(t)))) == pair}


def check_one_family_clebsches_equal():
    premise("standard-model.yukawa-pattern-two-rung-module")
    premise("standard-model.hyp-s-slot-statistics")
    ok = True
    for x, y, lep, qrk in ((W[3], W[4], ("L", "ec"), ("Q", "dc")), (V[3], V[4], ("L", "nuc"), ("Q", "uc"))):
        sign = -1 if x is W[3] else 1
        for a, b in SAMPLES:
            X = madd(msc(a, x), msc(b, y))
            f = form(X)
            cl = clebsch(f)
            ok = ok and op_weight(HYP, X) == F(sign, 2)
            ok = ok and meq(f, ftr(f)) and set(cl) == {lep, qrk}
            want = {abs(a), abs(b)} - {0}
            ok = ok and magnitudes(f, lep) == want == magnitudes(f, qrk)
    GA.check("every rung vector of either hypercharge: symmetric form, |y_e| = |y_d| and |y_nu| = |y_u|", ok)
    return ok


def check_family_factor_keeps_spectra():
    premise("standard-model.yukawa-pattern-two-rung-module")
    premise("standard-model.hyp-s-slot-statistics")
    ok = FAM != t3(FAM) and charpoly3(FAM)[2] != 0
    for x, lep, qrk in ((W[3], ("L", "ec"), ("Q", "dc")), (V[3], ("L", "nuc"), ("Q", "uc"))):
        cl = clebsch(form(x))
        for ye in cl[lep]:
            for yd in cl[qrk]:
                ce, cd = charpoly3(s3(ye, FAM)), charpoly3(s3(yd, FAM))
                sgn = 1 if ye == yd else -1
                ok = ok and all(ce[k] == sgn ** (k + 1) * cd[k] for k in range(3))
                Me, Md = s3(ye, FAM), s3(yd, FAM)
                ok = ok and charpoly3(m3(Me, t3(Me))) == charpoly3(m3(Md, t3(Md)))
    # control: the 126 entries separate the spectra
    cg = clebsch(form(mm(W[3], BL, CHI)))
    ok = ok and cg[("L", "ec")] == {F(-1)} and cg[("Q", "dc")] == {F(1, 3), F(-1, 3)}
    Me, Md = s3(F(-1), FAM), s3(F(1, 3), FAM)
    ok = ok and charpoly3(m3(Me, t3(Me))) != charpoly3(m3(Md, t3(Md)))
    GA.check("M_e = y_e F and M_d = y_d F: same spectra in magnitude for the 10, for any F; 126 control differs", ok)
    return ok

standard-model.frozen-point-pair-mixing:
"""standard-model.frozen-point-pair-mixing: exact checks.

Model: the five-mode module (pair modes 0, 1, 2 spanning W; rung modes 3, 4), creation v_i, annihilation w_i;
V_C = W + Wbar is spanned by the six pair-mode operators v_i, w_i (i <= 3 in the text's labels).
(1) Weights: [N_j, v_i] = delta_ij v_i and [N_j, w_i] = -delta_ij w_i for the three pair number operators,
    so the weights of V_C are +-e_i, none zero; the joint kernel of x -> ([N_1, x], [N_2, x], [N_3, x]) on
    V_C is zero (no nonzero vector is invariant under the maximal torus, so none under U(3)); the frozen point
    I = a v_1 + b w_1 is moved by N_1 for every sample (a, b) != 0.
(2) Stabiliser: for five nonzero vectors of C^3 the real stabiliser in u(3) (nine real generators) has real
    dimension 4 = dim u(2).
(3) Every pair-mode operator commutes with the rung mixing u(2) = span{v_a w_b : a, b rungs} and with N_R.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from pyutil import get_or_set
from tp_premise import premise

# ---------------------------------------------------------------------------
# The five-mode module Lambda(W + R_2) = Lambda(C^5), exact (sparse matrices {(row, col): Fraction}).
# Modes 0, 1, 2 are the pair modes (W), modes 3, 4 the two rung (slot) modes, the text's modes 4 and 5.
# v_i = creation (wedge), w_i = annihilation (contraction), v_i w_i + w_i v_i = 1.
# ---------------------------------------------------------------------------
NM = 5
PAIRS5, RUNGS5 = (0, 1, 2), (3, 4)
STATES = [frozenset(S) for k in range(NM + 1) for S in combinations(range(NM), k)]
SIDX = {S: i for i, S in enumerate(STATES)}
DIM5 = len(STATES)


def sp_from_action(act):
    M = {}
    for S in STATES:
        for T, c in act(S).items():
            if c != 0:
                M[(SIDX[T], SIDX[S])] = M.get((SIDX[T], SIDX[S]), F(0)) + c
    return {k: v for k, v in M.items() if v != 0}


def sp_mul(A, B):
    Bc = {}
    for (i, j), b in B.items():
        get_or_set(Bc, i, []).append((j, b))
    C = {}
    for (i, k), a in A.items():
        for j, b in Bc.get(k, ()):
            C[(i, j)] = C.get((i, j), F(0)) + a * b
    return {k: v for k, v in C.items() if v != 0}


def sp_add(*Ms):
    C = {}
    for M in Ms:
        for k, v in M.items():
            C[k] = C.get(k, F(0)) + v
    return {k: v for k, v in C.items() if v != 0}


def sp_scal(c, M):
    return {k: c * v for k, v in M.items() if c * v != 0}


def sp_eq(A, B):
    return sp_add(A, sp_scal(F(-1), B)) == {}


def sp_apply(M, vec):
    out = {}
    for (i, j), a in M.items():
        if j in vec:
            out[i] = out.get(i, F(0)) + a * vec[j]
    return {k: v for k, v in out.items() if v != 0}


ID5 = {(i, i): F(1) for i in range(DIM5)}
V5 = [sp_from_action(lambda S, i=i: GA.ext_wedge(i, {S: F(1)})) for i in range(NM)]
W5 = [sp_from_action(lambda S, i=i: GA.ext_contract([F(1) if j == i else F(0) for j in range(NM)], {S: F(1)}))
      for i in range(NM)]


def num(i):
    return sp_mul(V5[i], W5[i])


N_W = sp_add(*[num(i) for i in PAIRS5])
N_R = sp_add(*[num(i) for i in RUNGS5])
HYP = sp_add(sp_scal(F(1, 2), N_R), sp_scal(F(-1, 3), N_W))
T3 = sp_scal(F(1, 2), sp_add(num(3), sp_scal(F(-1), num(4))))
SU3 = [sp_mul(V5[i], W5[j]) for i in PAIRS5 for j in PAIRS5 if i != j]
SU2 = [sp_mul(V5[3], W5[4]), sp_mul(V5[4], W5[3]), T3]


def comm(A, B):
    return sp_add(sp_mul(A, B), sp_scal(F(-1), sp_mul(B, A)))


def weight(M, Q):
    """The eigenvalue of ad Q on M, or None if M is not an eigenvector."""
    c = comm(Q, M)
    if c == {}:
        return F(0)
    (i, j), a = next(iter(M.items()))
    q = c.get((i, j), F(0)) / a
    return q if sp_eq(c, sp_scal(q, M)) else None


def basis5(S):
    return {SIDX[frozenset(S)]: F(1)}

QI = GA.QI
AB_SAMPLES = [(F(1), F(0)), (F(0), F(1)), (F(2), F(1, 6)), (F(1), F(-1, 3)), (F(-3), F(5))]
C3_SAMPLES = [(1, 0, 0), (0, 1, 0), (1, QI(0, 1), 0), (QI(2, 1), -1, 3), (F(1, 2), QI(0, -2), QI(1, 1))]


def check_ambient_weights_are_nonzero():
    premise("standard-model.module-factorises-even-ground-elements-act")
    ok = True
    for i in PAIRS5:
        for j in PAIRS5:
            ok = ok and weight(V5[i], num(j)) == (F(1) if i == j else F(0))
            ok = ok and weight(W5[i], num(j)) == (F(-1) if i == j else F(0))
    ops = [V5[i] for i in PAIRS5] + [W5[i] for i in PAIRS5]
    keys = sorted({k for j in PAIRS5 for x in ops for k in comm(num(j), x)})
    M = [[comm(num(j), x).get(k, F(0)) for x in ops] for j in PAIRS5 for k in keys]
    ok = ok and len(GA.field_kernel(M)) == 0
    for a, b in AB_SAMPLES:
        I = sp_add(sp_scal(a, V5[0]), sp_scal(b, W5[0]))
        ok = ok and comm(num(0), I) != {}
    _tp_rv = (ok); assert _tp_rv is not False, "check_ambient_weights_are_nonzero"; return _tp_rv


def u3_basis():
    out = []
    for j in range(3):
        out.append([[QI(0, 1) if (r, c) == (j, j) else QI(0) for c in range(3)] for r in range(3)])
    for j, k in combinations(range(3), 2):
        out.append([[QI(1) if (r, c) == (j, k) else QI(-1) if (r, c) == (k, j) else QI(0) for c in range(3)]
                    for r in range(3)])
        out.append([[QI(0, 1) if (r, c) in ((j, k), (k, j)) else QI(0) for c in range(3)] for r in range(3)])
    return out


def check_generic_stabiliser_is_u2():
    ok = True
    basis = u3_basis()
    ok = ok and len(basis) == 9
    for v in C3_SAMPLES:
        v = [x if isinstance(x, QI) else QI(x) for x in v]
        imgs = [[sum((X[r][c] * v[c] for c in range(3)), QI(0)) for r in range(3)] for X in basis]
        real_rows = [[img[r].re for img in imgs] for r in range(3)] + [[img[r].im for img in imgs] for r in range(3)]
        ok = ok and len(GA.field_kernel(real_rows)) == 4
    _tp_rv = (ok); assert _tp_rv is not False, "check_generic_stabiliser_is_u2"; return _tp_rv


def check_vectors_commute_with_rung_mixing():
    premise("standard-model.module-factorises-even-ground-elements-act")
    ok = True
    mixing = [sp_mul(V5[a], W5[b]) for a in RUNGS5 for b in RUNGS5]
    ok = ok and len(mixing) == 4
    checked = 0
    for i in PAIRS5:
        for x in (V5[i], W5[i]):
            ok = ok and all(comm(x, g) == {} for g in mixing) and comm(x, N_R) == {}
            checked += 1
    ok = ok and checked == 6
    # control: a rung operator is moved by the rung number, [v_4, N_R] = -v_4
    ok = ok and comm(V5[3], N_R) == sp_scal(F(-1), V5[3])
    _tp_rv = (ok); assert _tp_rv is not False, "check_vectors_commute_with_rung_mixing"; return _tp_rv

standard-model.gauge-algebra-minimal-mas:
"""standard-model.gauge-algebra-minimal-massive-composite: exact checks.

The automorphisms of the hierarchy C^m (x) C^k are the maps A (x) B; their Lie algebra is the image of
u(m) + u(k) under (X, Y) -> X (x) 1 + 1 (x) Y, computed here as exact real ranks (Gaussian rationals split into
real and imaginary parts).
(1) Maximal hierarchy C^3 (x) C^3: 18 generators, image of dimension 17, derived algebra 16 = 8 + 8, centre of
    dimension 1: su(3) + su(3) + u(1), not the Standard Model algebra.
(2) Mass first exists at two constituents (the premise, checked at Gaussian-rational samples): one spinor gives
    p = pi pibar^T with det p = 0 (massless); two give det p = |<pi1 pi2>|^2, so p^2 = 2 det p = 2|<pi1 pi2>|^2,
    nonzero unless the spinors are aligned.
(3) Minimal massive hierarchy C^2 (x) C^3: 13 generators, image of dimension 12 = 4 + 9 - 1 = 3 + 8 + 1, derived
    algebra 11 = 3 + 8, centre 1; the kernel of the Lie algebra action is exactly the line of (i I_2, -i I_3)
    (the diagonal phase), and at the group level (lambda I_2, lambda^-1 I_3) acts trivially for a unit Gaussian
    lambda while (lambda I_2, lambda I_3) does not.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise

QI = GA.QI
SPINORS = [[QI(1), QI(0)], [QI(1, 1), QI(2)], [QI(2, -1), QI(F(1, 3), 1)], [QI(0, 3), QI(-1, 2)]]
LAM = QI(F(3, 5), F(4, 5))


def _basis_u(n):
    out = []
    for k in range(n):
        out.append({(k, k): QI(0, 1)})
    for j in range(n):
        for k in range(j + 1, n):
            out.append({(j, k): QI(1), (k, j): QI(-1)})
            out.append({(j, k): QI(0, 1), (k, j): QI(0, 1)})
    return out


def _act(X, Y, m, k):
    M = {}
    for (a, c), z in X.items():
        for b in range(k):
            key = (a * k + b, c * k + b)
            M[key] = M.get(key, QI(0)) + z
    for (b, d), z in Y.items():
        for a in range(m):
            key = (a * k + b, a * k + d)
            M[key] = M.get(key, QI(0)) + z
    return {kk: v for kk, v in M.items() if v}


def _real_row(M, N):
    row = [F(0)] * (2 * N * N)
    for (r, c), z in M.items():
        row[r * N + c] = z.re
        row[N * N + r * N + c] = z.im
    return row


def _mmul(A, B):
    out = {}
    for (r, c), z in A.items():
        for (c2, d), w in B.items():
            if c == c2:
                out[(r, d)] = out.get((r, d), QI(0)) + z * w
    return {kk: v for kk, v in out.items() if v}


def _comm(A, B):
    out = dict(_mmul(A, B))
    for kk, v in _mmul(B, A).items():
        out[kk] = out.get(kk, QI(0)) - v
    return {kk: v for kk, v in out.items() if v}


def _rank(mats, N):
    return GA.rank_of_vectors([_real_row(M, N) for M in mats]) if mats else 0


def _structure(m, k):
    """(generators, image dim, derived dim, A-side derived, B-side derived, centre dim, kernel basis)."""
    zm, zk = {}, {}
    A = [_act(X, zk, m, k) for X in _basis_u(m)]
    B = [_act(zm, Y, m, k) for Y in _basis_u(k)]
    N = m * k
    gens = A + B
    img = _rank(gens, N)
    pairs = lambda L: [_comm(L[i], L[j]) for i in range(len(L)) for j in range(i + 1, len(L))]
    der, dA, dB = _rank(pairs(gens), N), _rank(pairs(A), N), _rank(pairs(B), N)
    rows = []
    for j in range(len(gens)):
        cols = [_real_row(_comm(g, gens[j]), N) for g in gens]
        rows.extend([[cols[i][r] for i in range(len(gens))] for r in range(2 * N * N)])
    cent = []
    for c in GA.field_kernel(rows):
        M = {}
        for g, ci in zip(gens, c):
            for kk, z in g.items():
                M[kk] = M.get(kk, QI(0)) + z * QI(ci)
        cent.append({kk: v for kk, v in M.items() if v})
    kern = GA.field_kernel([[_real_row(g, N)[r] for g in gens] for r in range(2 * N * N)])
    return len(gens), img, der, dA, dB, _rank(cent, N), kern


def _det2(M):
    return M[0][0] * M[1][1] - M[0][1] * M[1][0]


def _momentum(spinors):
    p = [[QI(0), QI(0)], [QI(0), QI(0)]]
    for s in spinors:
        for A in range(2):
            for Ap in range(2):
                p[A][Ap] = p[A][Ap] + s[A] * s[Ap].conj()
    return p


def check_maximal_hierarchy_is_seventeen():
    n, img, der, dA, dB, cen, kern = _structure(3, 3)
    ok = (n, img, der, dA, dB, cen) == (18, 17, 16, 8, 8, 1) and len(kern) == 1
    GA.check("aut(C^3 x C^3): 18 generators, dimension 17 = 8 + 8 + 1", ok)
    return ok


def check_mass_first_at_two_constituents():
    premise("mass.mass-symplectic-area-two-twistor-formula")
    ok = True
    for s in SPINORS:
        ok = ok and _det2(_momentum([s])) == QI(0)
    nonzero = 0
    for i in range(len(SPINORS)):
        for j in range(i + 1, len(SPINORS)):
            a, b = SPINORS[i], SPINORS[j]
            br = a[0] * b[1] - a[1] * b[0]
            d = _det2(_momentum([a, b]))
            ok = ok and d == br * br.conj() and d.im == 0
            nonzero += 1 if d != QI(0) else 0
    aligned = [QI(2, 1) * x for x in SPINORS[1]]
    ok = ok and _det2(_momentum([SPINORS[1], aligned])) == QI(0) and nonzero == 6
    GA.check("one spinor: det p = 0; two: det p = |<pi1 pi2>|^2 (m^2 = 2 det p), zero only when aligned", ok)
    return ok


def check_minimal_massive_is_standard_model():
    premise("mass.mass-symplectic-area-two-twistor-formula")
    n, img, der, dA, dB, cen, kern = _structure(2, 3)
    ok = (n, img, der, dA, dB, cen) == (13, 12, 11, 3, 8, 1) and img == 4 + 9 - 1 == 3 + 8 + 1
    # the kernel line: coefficient vector proportional to (i E_00 + i E_11) - (i E_00 + i E_11 + i E_22) parts
    ok = ok and len(kern) == 1
    v = kern[0]
    X = {}
    for c, M in zip(v[:4], _basis_u(2)):
        for kk, z in M.items():
            X[kk] = X.get(kk, QI(0)) + z * QI(c)
    Y = {}
    for c, M in zip(v[4:], _basis_u(3)):
        for kk, z in M.items():
            Y[kk] = Y.get(kk, QI(0)) + z * QI(c)
    X = {kk: z for kk, z in X.items() if z}
    Y = {kk: z for kk, z in Y.items() if z}
    s = X.get((0, 0))
    ok = ok and s is not None and s.re == 0 and X == {(0, 0): s, (1, 1): s}
    ok = ok and Y == {(0, 0): -s, (1, 1): -s, (2, 2): -s}
    # group level: (lam I2, lam^-1 I3) acts as lam * lam^-1 = 1 on every basis tensor; (lam I2, lam I3) as lam^2
    inv = QI(1) / LAM
    ok = ok and LAM * inv == QI(1) and LAM * LAM != QI(1) and LAM * LAM.conj() == QI(1)
    GA.check("aut(C^2 x C^3): 13 generators, dimension 12 = su(2) + su(3) + u(1); kernel = diagonal phase", ok)
    return ok

standard-model.generation-ten-under-pati:
"""standard-model.generation-ten-under-pati-salam: exact checks.

The five-mode module as 32 x 32 rational matrices (pair modes 0, 1, 2; slot modes 3, 4, the text's 4
and 5), the sixteen being the states of even total mode number. su(2)_L = {v_4 w_5, v_5 w_4, (N_4 - N_5)/2},
su(2)_R = {v_4 v_5, w_5 w_4, (N_4 + N_5 - 1)/2} as in the premise; Casimir C = T_3^2 + (T_+ T_- + T_- T_+)/2.
B - L = 1 - (2/3) N_W. Species by (pairs, slots) occupied: nu^c (0,0), u^c (2,0), Q (1,1), L (3,1),
e^c (0,2), d^c (2,2).
(1) C_L and C_R are diagonal on the sixteen, (3/4, 0) on Q and L and (0, 3/4) on the four singlets;
    B - L is 1/3, -1, -1/3, -1/3, 1, 1 on Q, L, u^c, d^c, e^c, nu^c.
(2) The sixteen is (2,1,4) + (1,2,4bar): the slot-doublet half carries B - L weights {1/3 x 3, -1},
    the slot-singlet half {-1/3 x 3, 1} (conjugate 4s), and the commutant of the 15 pair bivectors
    (su(4)) on each half of eight is four-dimensional (two copies of one irreducible 4).
(3) Under the 21 (adjoint action X -> [B, X]) the span of the orbit of a slot Majorana is the four
    slot Majoranas and that of a pair Majorana the six pair Majoranas; on the four, C_L = C_R = 3/4
    (the bidoublet (2,2,1)); on the six su(2)_L and su(2)_R act trivially (the (1,1,6)).
"""
from fractions import Fraction as F

import GA
from pyutil import get_or_set
import fock
from tp_premise import premise

# ---------------------------------------------------------------------------
# The five-mode module Lambda(W + R_2) = Lambda(C^5), exact.
# States are bitmasks s in 0..31; mode m is occupied when bit m is set.
# Modes 0, 1, 2 are the three pair modes (W), modes 3, 4 the two slot (rung)
# modes, the text's modes 4 and 5. Operators are sparse matrices
# {(row, col): Fraction}; Jordan-Wigner sign (-1)^(occupied modes below m).
# ---------------------------------------------------------------------------
NM = 5
DIM = 32
PAIRS = (0, 1, 2)
SLOTS = (3, 4)


def nw(s):
    return sum(1 for m in PAIRS if s >> m & 1)


def nr(s):
    return sum(1 for m in SLOTS if s >> m & 1)


def ntot(s):
    return nw(s) + nr(s)


mm, madd, msc, msub = fock.mm, fock.madd, fock.msc, fock.msub
comm, meq, restrict = fock.comm, fock.meq, fock.restrict


def gam(p):
    """Majorana p = 0..9 of mode p // 2 in the real form: gamma_{2m} = v_m + w_m (square +1),
    g_{2m+1} = w_m - v_m (square -1). The text's gamma_{2m+1} = I g_{2m+1}, I^2 = -1 central."""
    return fock.majorana(p, NM)


ONE = fock.eye(DIM)
V = [fock.cre(m, NM) for m in range(NM)]  # v_m, creation
W = [fock.ann(m, NM) for m in range(NM)]  # w_m, annihilation
NUM = [fock.num(m, NM) for m in range(NM)]  # n_m


class Span:
    """Incremental exact span of sparse vectors (dicts with hashable keys), reduced row echelon."""

    def __init__(self):
        self.piv, self.where = {}, {}

    def reduce(self, v):
        v = {k: x for k, x in v.items() if x}
        for k in [k for k in v if k in self.piv]:
            c = v.pop(k)
            for kk, xx in self.piv[k].items():
                if kk != k:
                    y = v.get(kk, 0) - c * xx
                    if y:
                        v[kk] = y
                    else:
                        v.pop(kk, None)
        return v

    def add(self, v):
        v = self.reduce(v)
        if not v:
            return False
        k0 = next(iter(v))
        c0 = v[k0]
        v = {k: x / c0 for k, x in v.items()}
        for p in list(self.where.get(k0, ())):
            row = self.piv[p]
            c = row.pop(k0)
            for kk, xx in v.items():
                if kk != k0:
                    y = row.get(kk, 0) - c * xx
                    if y:
                        row[kk] = y
                        get_or_set(self.where, kk, set()).add(p)
                    else:
                        row.pop(kk, None)
                        self.where.get(kk, set()).discard(p)
        self.where.pop(k0, None)
        self.piv[k0] = v
        for kk in v:
            if kk != k0:
                get_or_set(self.where, kk, set()).add(k0)
        return True

    def __len__(self):
        return len(self.piv)


def rank(vecs):
    """Exact rank of sparse vectors (dicts with hashable keys)."""
    sp = Span()
    for v in vecs:
        sp.add(v)
    return len(sp)


def in_span(vecs, v):
    sp = Span()
    for u in vecs:
        sp.add(u)
    return not sp.reduce(v)


def bilinears():
    """The 45 products g_p g_q, p < q, of the real-form Majoranas (the bivectors of the ten,
    up to the central factors of I)."""
    G = [gam(p) for p in range(2 * NM)]
    return {(p, q): mm(G[p], G[q]) for p in range(2 * NM) for q in range(p + 1, 2 * NM)}


def commutant_dim(gens, states):
    """Dimension of {X on span(states) : [X, g] = 0 for all g}, by exact sparse elimination."""
    S = list(states)
    Sset = set(S)
    rows = []
    for g in gens:
        g = restrict(g, S)
        grow, gcol = {}, {}
        for (r, c), x in g.items():
            get_or_set(grow, r, []).append((c, x))
            get_or_set(gcol, c, []).append((r, x))
        for r in S:
            for c in S:
                eq = {}
                # (X g)_{rc} = sum_k X_{rk} g_{kc};  (g X)_{rc} = sum_k g_{rk} X_{kc}
                for k, x in gcol.get(c, ()):
                    eq[(r, k)] = eq.get((r, k), 0) + x
                for k, x in grow.get(r, ()):
                    eq[(k, c)] = eq.get((k, c), 0) - x
                eq = {k: x for k, x in eq.items() if x}
                if eq:
                    rows.append(eq)
    return len(S) * len(S) - rank(rows)

PAIR_G = tuple(range(6))
SLOT_G = (6, 7, 8, 9)
SPECIES = {(0, 0): "nuc", (2, 0): "uc", (1, 1): "Q", (3, 1): "L", (0, 2): "ec", (2, 2): "dc"}


def species(s):
    return SPECIES[(nw(s), nr(s))]


def su2(left):
    if left:
        return [mm(V[3], W[4]), mm(V[4], W[3]), msc(F(1, 2), msub(NUM[3], NUM[4]))]
    return [mm(V[3], V[4]), mm(W[4], W[3]), msc(F(1, 2), madd(NUM[3], NUM[4], msc(-1, ONE)))]


def casimir(left):
    tp, tm, t3 = su2(left)
    return madd(mm(t3, t3), msc(F(1, 2), madd(mm(tp, tm), mm(tm, tp))))


def ad_casimir(left, X):
    tp, tm, t3 = su2(left)
    a3 = comm(t3, comm(t3, X))
    apm = madd(comm(tp, comm(tm, X)), comm(tm, comm(tp, X)))
    return madd(a3, msc(F(1, 2), apm))


def orbit_span(start, gens):
    sp = Span()
    sp.add(start)
    span, frontier = [start], [start]
    while frontier:
        new = []
        for X in frontier:
            for g in gens:
                Y = comm(g, X)
                if sp.add(Y):
                    span.append(Y)
                    new.append(Y)
        frontier = new
    return span


