         lp((1, (-4, 0, 0, 0)), (7, (-1, -1, -1, -1)))]
MONOMIALS = [(-6, 0, 0, 0), (-3, 0, -1, -1), (-2, -1, 0, -1), (0, -2, 0, -2), (0, -1, -1, -1), (-1, -1, 0, 0),
