QI = GA.QI
N = 5
STATES = [frozenset(c) for r in range(N + 1) for c in combinations(range(1, N + 1), r)]
FULL = frozenset(range(1, N + 1))
EVEN = [S for S in STATES if len(S) % 2 == 0]
NAMES = {(0, 0): "nu^c", (0, 2): "u^c", (1, 1): "Q", (1, 3): "L", (2, 0): "e^c", (2, 2): "d^c"}


def act(op, st):
    out = {}
    for (kind, i), c in op.items():
        for S, a in st.items():
            if kind == "v" and i not in S:
                T = S | {i}
            elif kind == "w" and i in S:
                T = S - {i}
            else:
                continue
            sign = -1 if sum(1 for j in S if j < i) % 2 else 1
            out[T] = QI(0) + out.get(T, QI(0)) + c * a * sign
    return {k: v for k, v in out.items() if v != 0}


def perm_sign(seq):
    s = 1
    for i in range(len(seq)):
        for j in range(i + 1, len(seq)):
            if seq[i] > seq[j]:
                s = -s
    return s


def B(psi, phi):
    tot = QI(0)
    for S, a in psi.items():
        Sc = FULL - S
        if Sc in phi:
            k = len(S)
            tot = tot + a * phi[Sc] * ((-1) ** (k * (k - 1) // 2) * perm_sign(sorted(S) + sorted(Sc)))
    return tot


def jk(S):
    return len(S & {4, 5}), len(S & {1, 2, 3})


def norm2(z):
    z = QI(0) + z
    return z.re * z.re + z.im * z.im


def mass_form(c):
    """{species pair: set of |entry|^2} over the nonzero entries of M_c on the sixteen."""
    out = {}
    for S in EVEN:
        for T in EVEN:
            val = B({S: QI(1)}, act(c, {T: QI(1)}))
            if val != 0:
                key = tuple(sorted((NAMES[jk(S)], NAMES[jk(T)])))
                get_or_set(out, key, set()).add(norm2(val))
    return out


def star(c):
    """The conjugate-linear antiautomorphism on vectors: v_j* = w_j, w_j* = v_j."""
    swap = {"v": "w", "w": "v"}
    return {(swap[k], j): (QI(0) + z).conj() for (k, j), z in c.items()}


SAMPLES = [(QI(5), QI(F(2, 7))), (QI(3, 4), QI(1, -2)), (QI(F(-2, 3)), QI(0, 5)), (QI(1, 1), QI(F(1, 2), 3))]


def vev(a, b):
    return {("v", 4): a, ("w", 4): b}


def check_mass_form_magnitudes():
    premise("standard-model.yukawa-pattern-two-rung-module")
    premise("standard-model.hyp-s-slot-statistics")
    ok = True
    for a, b in SAMPLES:
        A2, B2 = norm2(a), norm2(b)
        ok = ok and mass_form(vev(a, b)) == {("L", "nu^c"): {A2}, ("Q", "u^c"): {A2},
                                             ("L", "e^c"): {B2}, ("Q", "d^c"): {B2}}
    # one sample by hand: a = 5, b = 2/7 gives |a|^2 = 25, |b|^2 = 4/49
    ok = ok and mass_form(vev(QI(5), QI(F(2, 7))))[("L", "nu^c")] == {25}
    ok = ok and mass_form(vev(QI(5), QI(F(2, 7))))[("Q", "d^c")] == {F(4, 49)}
    GA.check("one vev: M_c has |a| on (L,nu^c), (Q,u^c) and |b| on (L,e^c), (Q,d^c)", ok)
    return ok


def check_conjugate_reading_gives_four_equal_masses():
    premise("standard-model.imported-tower-commuting-copies-fock-module")
    premise("standard-model.yukawa-pattern-two-rung-module")
    premise("standard-model.hyp-s-slot-statistics")
    ok = True
    for a, b in SAMPLES:
        cs = star(vev(a, b))
        ok = ok and cs == {("w", 4): a.conj(), ("v", 4): b.conj()}
        up = mass_form(cs)
        down = mass_form(vev(a, b))
        m = {norm2(b)}
        ok = ok and up[("Q", "u^c")] == m and up[("L", "nu^c")] == m
        ok = ok and down[("Q", "d^c")] == m and down[("L", "e^c")] == m
        # read through c itself: m_u^2 / m_d^2 = |a|^2 / |b|^2
        ok = ok and next(iter(down[("Q", "u^c")])) * norm2(b) == next(iter(down[("Q", "d^c")])) * norm2(a)
    GA.check("one vev: through c* the four Dirac masses are all |b|; through c, m_u/m_d = |a|/|b|", ok)
    return ok


def check_rung_terms_select_isospin_components():
    premise("standard-model.ten-transported-ambient-space-doublets-are")
    premise("standard-model.hyp-s-slot-statistics")
    ok = True
    for kind, t3 in (("v", F(-1, 2)), ("w", F(1, 2))):
        seen = set()
        for S in EVEN:
            for T in EVEN:
                if B({S: QI(1)}, act({(kind, 4): QI(1)}, {T: QI(1)})) != 0:
                    for U in (S, T):
                        if NAMES[jk(U)] in ("L", "Q"):
                            seen.add(F((4 in U) - (5 in U), 2))
        ok = ok and seen == {t3}
    GA.check("one vev: the v_4 term couples T_3 = -1/2 members of L, Q; the w_4 term T_3 = +1/2", ok)
    return ok


HALF, I_ = F(1, 2), QI(0, 1)


def e45(st):
    return act({("v", 4): QI(1)}, act({("w", 5): QI(1)}, st))


def e54(st):
    return act({("v", 5): QI(1)}, act({("w", 4): QI(1)}, st))


def t3(st):
    return {S: z * (HALF * ((4 in S) - (5 in S))) for S, z in st.items() if (4 in S) != (5 in S)}


def hyp(st):
    return {S: z * F(3 * len(S & {4, 5}) - 2 * len(S & {1, 2, 3}), 6) for S, z in st.items()
            if 3 * len(S & {4, 5}) != 2 * len(S & {1, 2, 3})}


def plus(f, g, cf, cg):
    def h(st):
        out = {}
        for k, v in f(st).items():
            out[k] = out.get(k, QI(0)) + cf * v
        for k, v in g(st).items():
            out[k] = out.get(k, QI(0)) + cg * v
        return {k: v for k, v in out.items() if v != 0}
    return h


# the real Lie algebra su(2) + u(1)_Y by anti-Hermitian generators
GENS = [plus(e45, e54, I_, I_), plus(e45, e54, QI(1), QI(-1)), plus(t3, t3, I_, QI(0)), plus(hyp, hyp, I_, QI(0))]


def flat(op):
    out = []
    for S in STATES:
        st = op({S: QI(1)})
        for T in STATES:
            z = QI(0) + st.get(T, QI(0))
            out += [z.re, z.im]
    return out


def comm_vec(g, c):
    return flat(lambda st: {k: v for k, v in
                            [(T, g(act(c, st)).get(T, QI(0)) - act(c, g(st)).get(T, QI(0))) for T in STATES]
                            if v != 0})


def vec(c):
    return flat(lambda st: act(c, st))


def check_breaking_to_one_u1():
    premise("standard-model.ten-transported-ambient-space-doublets-are")
    ok = True
    # hand values: [i(E45 + E54), v_4] = i v_5, [E45 - E54, v_4] = -v_5, [i T_3, v_4] = [i Y, v_4] = (i/2) v_4,
    # [i T_3, w_4] = [i Y, w_4] = (-i/2) w_4
    v4, w4 = {("v", 4): QI(1)}, {("w", 4): QI(1)}
    ok = ok and comm_vec(GENS[0], v4) == vec({("v", 5): QI(0, 1)})
    ok = ok and comm_vec(GENS[1], v4) == vec({("v", 5): QI(-1)})
    ok = ok and comm_vec(GENS[2], v4) == vec({("v", 4): QI(0, F(1, 2))}) == comm_vec(GENS[3], v4)
    ok = ok and comm_vec(GENS[2], w4) == vec({("w", 4): QI(0, F(-1, 2))}) == comm_vec(GENS[3], w4)
    for a, b in SAMPLES + [(QI(1), QI(0)), (QI(0), QI(2, -1))]:
        c = {k: v for k, v in vev(a, b).items() if v != 0}
        cols = [comm_vec(g, c) for g in GENS]
        # a one-dimensional stabiliser, spanned by i (T_3 - Y)
        ok = ok and 4 - GA.field_rank(cols) == 1
        ok = ok and cols[2] == cols[3] and any(x != 0 for x in cols[2])
    GA.check("one vev: a vector along one rung breaks su(2) + u(1)_Y to the u(1) of T_3 - Y", ok)
    return ok

standard-model.pair-mixing-not-colour:
"""standard-model.pair-mixing-not-colour: exact checks.

The conformal spinor's Fock space Lambda(W), W = span(v_1, v_2, v_3), is built as 8 x 8 matrices over
Q(i) (GA.QI) in the occupation basis; v_a creates, w_a = v_a^dagger contracts. A real form so(2,4) is
generated by six Clifford generators of signature (2,4): v_1 + w_1, v_2 + w_2 (square +1, Hermitian)
and v_1 - w_1, v_2 - w_2, v_3 - w_3, i(v_3 + w_3) (square -1, anti-Hermitian); its 15 bivectors
(1/2) g_m g_n span the conformal algebra. u(3) is spanned over R by i E_aa, E_ab - E_ba,
i(E_ab + E_ba) with E_ab = v_a w_b.
(i) The traceless parts of v_a w_b lie in the complex span of the 15 bivectors (inside so(6,C));
u(3) is anti-Hermitian of real dimension 9; the compact part of so(2,4) (its anti-Hermitian
elements) has real dimension 7 = dim so(2) + so(4); u(3) mod scalars is not in the real span of
so(2,4). With the imported maximal-compact Fact this gives (i).
(ii) The commutant of the 15 bivectors in M_8(C) is computed by exact elimination: dimension 2,
spanned by the projections onto Lambda^even W and Lambda^odd W; every one of the nine u(3) generators
fails to commute with some bivector.
(iii) On Fock (x) C^3 (the label copy carried by the hierarchy bundle), the conformal bivectors act as
X (x) 1 and the colour generators as 1 (x) T: they commute, while the pair mixing on the Fock factor
does not. The remaining sentences of (iii) are readings and are not checked.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from tp_premise import premise

QI = GA.QI
STATES = [frozenset(c) for r in range(4) for c in combinations((1, 2, 3), r)]
IDX = {S: i for i, S in enumerate(STATES)}
DIM = 8


def zeros(n=DIM):
    return [[QI(0)] * n for _ in range(n)]


def mode(kind, a):
    M = zeros()
    for S in STATES:
        if kind == "v" and a not in S:
            T = S | {a}
        elif kind == "w" and a in S:
            T = S - {a}
        else:
            continue
        sign = -1 if sum(1 for j in S if j < a) % 2 else 1
        M[IDX[T]][IDX[S]] = QI(sign)
    return M


def mm(A, B):
    return [[sum((A[i][k] * B[k][j] for k in range(len(B))), QI(0)) for j in range(len(B[0]))] for i in range(len(A))]


def lin(*terms):
    n = len(terms[0][1])
    return [[sum((QI(0) + c * M[i][j] for c, M in terms), QI(0)) for j in range(n)] for i in range(n)]


def dag(A):
    return [[A[j][i].conj() for j in range(len(A))] for i in range(len(A))]


def comm(A, B):
    return lin((QI(1), mm(A, B)), (QI(-1), mm(B, A)))


def is_zero(A):
    return all(x == 0 for row in A for x in row)


def ident(n=DIM):
    return [[QI(1) if i == j else QI(0) for j in range(n)] for i in range(n)]


V = {a: mode("v", a) for a in (1, 2, 3)}
W = {a: mode("w", a) for a in (1, 2, 3)}
I_ = QI(0, 1)
GENS = [lin((QI(1), V[1]), (QI(1), W[1])), lin((QI(1), V[2]), (QI(1), W[2])),
        lin((QI(1), V[1]), (QI(-1), W[1])), lin((QI(1), V[2]), (QI(-1), W[2])),
        lin((QI(1), V[3]), (QI(-1), W[3])), lin((I_, V[3]), (I_, W[3]))]
BIV = [lin((QI(F(1, 2)), mm(GENS[m], GENS[n]))) for m, n in combinations(range(6), 2)]
E = {(a, b): mm(V[a], W[b]) for a in (1, 2, 3) for b in (1, 2, 3)}
U3 = ([lin((I_, E[(a, a)])) for a in (1, 2, 3)]
      + [lin((QI(1), E[(a, b)]), (QI(-1), E[(b, a)])) for a, b in combinations((1, 2, 3), 2)]
      + [lin((I_, E[(a, b)]), (I_, E[(b, a)])) for a, b in combinations((1, 2, 3), 2)])


def flat_c(A):
    return [x for row in A for x in row]


def flat_r(A):
    return [y for x in flat_c(A) for y in (x.re, x.im)]


def traceless(A):
    t = sum((A[i][i] for i in range(DIM)), QI(0)) / DIM
    return lin((QI(1), A), (-t, ident()))


def check_pair_mixing_is_compact_and_outside_the_real_form():
    premise("standard-model.imported-maximal-compact-subgroups")
    ok = True
    # the six generators have the stated squares: signature (2, 4)
    squares = [mm(g, g)[0][0] for g in GENS]
    ok = ok and squares == [1, 1, -1, -1, -1, -1]
    ok = ok and (len(GENS) == len(squares) and all(mm(g, g) == lin((sq, ident())) for g, sq in zip(GENS, squares)))
    # traceless parts of v_a w_b lie in the complex span of the 15 bivectors
    base = [flat_c(X) for X in BIV]
    ok = ok and GA.field_rank(base) == 15
    ok = ok and all(GA.field_rank(base + [flat_c(traceless(E[k]))]) == 15 for k in E)
    # u(3): anti-Hermitian, real dimension 9
    ok = ok and all(dag(X) == lin((QI(-1), X)) for X in U3)
    ok = ok and GA.mat_rank([flat_r(X) for X in U3]) == 9
    # compact part of so(2,4): every bivector is Hermitian or anti-Hermitian; 7 anti-Hermitian
    herm = [X for X in BIV if dag(X) == X]
    anti = [X for X in BIV if dag(X) == lin((QI(-1), X))]
    ok = ok and len(herm) + len(anti) == 15 and len(anti) == 7
    # u(3) mod scalars is not inside the real span of so(2,4)
    real_so = [flat_r(X) for X in BIV]
    ok = ok and GA.mat_rank(real_so) == 15
    ok = ok and GA.mat_rank(real_so + [flat_r(traceless(X)) for X in U3]) > 15
    ok = ok and 9 > len(anti)
    GA.check("pair mixing (i): u(3) compact of dimension 9 > 7, inside so(6,C) but not in so(2,4)", ok)
    return ok


def check_commutant_is_two_dimensional():
    ok = True
    # unknown M (64 entries); equations (M X - X M)_ij = 0 for the 15 bivectors
    rows = []
    for X in BIV:
        for i in range(DIM):
            for j in range(DIM):
                row = [QI(0)] * (DIM * DIM)
                for k in range(DIM):
                    row[i * DIM + k] = row[i * DIM + k] + X[k][j]
                    row[k * DIM + j] = row[k * DIM + j] - X[i][k]
                rows.append(row)
    ok = ok and DIM * DIM - GA.field_rank(rows) == 2
    even = [[QI(1) if i == j and len(STATES[i]) % 2 == 0 else QI(0) for j in range(DIM)] for i in range(DIM)]
    odd = lin((QI(1), ident()), (QI(-1), even))
    ok = ok and all(is_zero(comm(P, X)) for P in (even, odd) for X in BIV)
    ok = ok and sum(1 for i in range(DIM) if even[i][i] == 1) == 4
    # every u(3) generator fails to commute with some bivector
    ok = ok and all(any(not is_zero(comm(Uk, X)) for X in BIV) for Uk in U3)
    GA.check("pair mixing (ii): the commutant of so(2,4) on Lambda(W) is C + C; u(3) is not internal", ok)
    return ok


def skron(A, B):
    """Sparse Kronecker product {(row, col): value}."""
    m = len(B)
    out = {}
    for i, row in enumerate(A):
        for j, x in enumerate(row):
            if x != 0:
                for k, brow in enumerate(B):
                    for l, y in enumerate(brow):
                        if y != 0:
                            out[(i * m + k, j * m + l)] = x * y
    return out


def smm(A, B):
    out = {}
    for (i, k), x in A.items():
        for (k2, j), y in B.items():
            if k == k2:
                out[(i, j)] = out.get((i, j), QI(0)) + x * y
    return {k: v for k, v in out.items() if v != 0}


def scomm_zero(A, B):
    AB, BA = smm(A, B), smm(B, A)
    keys = set(AB) | set(BA)
    return all(AB.get(k, QI(0)) == BA.get(k, QI(0)) for k in keys)


def unit3(a, b):
    M = [[QI(0)] * 3 for _ in range(3)]
    M[a][b] = QI(1)
    return M


# colour su(3) on the label C^3
COLOUR = ([lin((QI(1), unit3(a, b)), (QI(-1), unit3(b, a))) for a, b in combinations(range(3), 2)]
          + [lin((I_, unit3(a, b)), (I_, unit3(b, a))) for a, b in combinations(range(3), 2)]
          + [lin((I_, unit3(0, 0)), (-I_, unit3(1, 1))), lin((I_, unit3(1, 1)), (-I_, unit3(2, 2)))])


def check_colour_on_the_label_copy_commutes():
    premise("standard-model.connection-forced")
    one3, one8 = ident(3), ident()
    conf = [skron(X, one3) for X in BIV]
    col = [skron(one8, T) for T in COLOUR]
    ok = len(COLOUR) == 8 and len(conf) == 15
    # su(3) is 8-dimensional over R: the colour generators are independent
    ok = ok and GA.mat_rank([flat_r(T) for T in COLOUR]) == 8
    ok = ok and all(scomm_zero(A, B) for A in conf for B in col)
    # the pair mixing on the Fock factor does not commute with the conformal generators
    ok = ok and all(any(not scomm_zero(skron(Uk, one3), A) for A in conf) for Uk in U3)
    GA.check("pair mixing (iii): colour on the label copy commutes with the conformal action", ok)
    return ok

standard-model.proton-decay-only-through:
"""standard-model.proton-decay-only-through-slot-pair: exact checks.

Five-mode module Lambda(C^5), occupation basis (pairs 1, 2, 3; slots/rungs 4, 5), v_a creation and
w_a contraction. The ten Majoranas are g_a+ = v_a + w_a (square +1) and g_a- = v_a - w_a
(square -1), real, so the 45 bivectors (1/2) g_m g_n act by rational matrices; the slot generators
are the four g_4+-, g_5+-, the pair generators the six g_1+-..g_3+-. On the sixteen (even states)
chi = -(-1)^(N_4 + N_5) (+1 on Q, L; -1 on u^c, d^c, e^c, nu^c) and B - L = 1 - (2/3) k.
(1) n_B = ((B - L) + chi)/4 and n_L = (chi - 3(B - L))/4 reproduce every species' baryon and
lepton number (hand table) on all 16 states, and 3 n_B + n_L = chi.
(2) The 21 split-preserving bivectors commute with chi on the sixteen, the 24 mixing ones
anticommute with it (and so flip chi on every state they do not annihilate).
(3) p -> e+ pi0: from the species numbers, Delta(B - L) = 0 and Delta(3 n_B + n_L) = -4, so the
process changes chi and no product of the 21 can mediate it; the mixing bivectors can.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from tp_premise import premise

N = 5
STATES = [frozenset(c) for r in range(N + 1) for c in combinations(range(1, N + 1), r)]
EVEN = [S for S in STATES if len(S) % 2 == 0]
NAMES = {(0, 0): "nu^c", (0, 2): "u^c", (1, 1): "Q", (1, 3): "L", (2, 0): "e^c", (2, 2): "d^c"}
SLOT_MODES, PAIR_MODES = (4, 5), (1, 2, 3)


def act(op, st):
    out = {}
    for (kind, i), c in op.items():
        for S, a in st.items():
            if kind == "v" and i not in S:
                T = S | {i}
            elif kind == "w" and i in S:
                T = S - {i}
            else:
                continue
            sign = -1 if sum(1 for j in S if j < i) % 2 else 1
            out[T] = out.get(T, 0) + sign * c * a
    return {k: v for k, v in out.items() if v != 0}


def majorana(a, s):
    return {("v", a): F(1), ("w", a): F(s)}


MAJ = [(a, s) for a in PAIR_MODES + SLOT_MODES for s in (1, -1)]


def bivector(m, n):
    return lambda st: {k: v / 2 for k, v in act(majorana(*m), act(majorana(*n), st)).items()}


BIVECTORS = [((m, n), bivector(m, n)) for m, n in combinations(MAJ, 2)]


def jk(S):
    return len(S & {4, 5}), len(S & {1, 2, 3})


def chi(S):
    return -(-1) ** len(S & {4, 5})


def b_minus_l(S):
    return 1 - F(2, 3) * jk(S)[1]


def nB(S):
    return (b_minus_l(S) + chi(S)) / 4


def nL(S):
    return (chi(S) - 3 * b_minus_l(S)) / 4


def check_baryon_and_lepton_number_from_chi():
    premise("standard-model.hyp-s-slot-statistics")
    premise("standard-model.automorphisms-preserve-slot-pair-split-are")
    table = {"Q": (F(1, 3), 0), "u^c": (F(-1, 3), 0), "d^c": (F(-1, 3), 0),
             "L": (0, 1), "e^c": (0, -1), "nu^c": (0, -1)}
    ok = len(EVEN) == 16
    for S in EVEN:
        ok = ok and (nB(S), nL(S)) == table[NAMES[jk(S)]]
        ok = ok and 3 * nB(S) + nL(S) == chi(S)
    ok = ok and sorted(chi(S) for S in EVEN) == [-1] * 8 + [1] * 8
    GA.check("proton: n_B = ((B-L) + chi)/4, n_L = (chi - 3(B-L))/4 on every state, 3 n_B + n_L = chi", ok)
    return ok


def check_chi_commutes_with_21_and_anticommutes_with_24():
    premise("standard-model.automorphisms-preserve-slot-pair-split-are")
    ok = len(BIVECTORS) == 45
    preserving = mixing = 0
    for (m, n), X in BIVECTORS:
        mixes = (m[0] in SLOT_MODES) != (n[0] in SLOT_MODES)
        for S in EVEN:
            img = X({S: F(1)})
            # X chi e_S = chi(S) X e_S; chi X e_S = sum chi(T) X_TS e_T
            if mixes:
                ok = ok and all(chi(T) == -chi(S) for T in img)
            else:
                ok = ok and all(chi(T) == chi(S) for T in img)
        # every bivector acts nontrivially on the sixteen
        ok = ok and any(X({S: F(1)}) for S in EVEN)
        mixing += mixes
        preserving += not mixes
    ok = ok and (preserving, mixing) == (21, 24)
    GA.check("proton: the 21 split-preserving bivectors commute with chi, the 24 mixing ones anticommute", ok)
    return ok


def check_proton_channel_needs_mixing():
    premise("standard-model.hyp-s-slot-statistics")
    premise("standard-model.automorphisms-preserve-slot-pair-split-are")
    by_species = {}
    for S in EVEN:
        by_species[NAMES[jk(S)]] = (nB(S), nL(S), b_minus_l(S), chi(S))
    quark = by_species["Q"]
    # p = three quarks of Q; e+ is the e^c state; pi0 carries nothing
    initial = tuple(3 * v for v in quark[:2])
    final = by_species["e^c"][:2]
    d_bl = (final[0] - final[1]) - (initial[0] - initial[1])
    d_chi = (3 * final[0] + final[1]) - (3 * initial[0] + initial[1])
    ok = initial == (1, 0) and final == (0, -1) and d_bl == 0 and d_chi == -4
    ok = ok and (final[0] - initial[0], final[1] - initial[1]) == (-1, -1)
    # a product of split-preserving bivectors keeps chi; a single mixing bivector flips it
    preserving = [X for (m, n), X in BIVECTORS if (m[0] in SLOT_MODES) == (n[0] in SLOT_MODES)]
    mixing = [X for (m, n), X in BIVECTORS if (m[0] in SLOT_MODES) != (n[0] in SLOT_MODES)]
    for S in EVEN:
        for X in preserving[:7]:
            for Yb in preserving[7:14]:
                ok = ok and all(chi(T) == chi(S) for T in X(Yb({S: F(1)})))
    ok = ok and all(any(chi(T) != chi(S) for S in EVEN for T in X({S: F(1)})) for X in mixing)
    GA.check("proton: p -> e+ pi0 has Delta(B-L) = 0, Delta(3 n_B + n_L) = -4: only the mixing generators", ok)
    return ok

standard-model.quarks-leptons-two-level-:
"""standard-model.quarks-leptons-two-level-fermion-content: exact checks.

The hypercharge generator is y = (3i I_2, -2i I_3), the centre of s(u(2) + u(3)) (it commutes with every generator
and has total trace 0 on C^5); its weight q on a representation is read off as the scalar by which it acts, and
Y = q/6. Weights are computed from the generator (diagonal entries summed over occupied modes), not typed in.
(1) On the cells C^2 (x) C^3 (tensor action X (x) 1 + 1 (x) Y) y acts as the scalar i: q = 1, Y = 1/6; the
    representation is irreducible (commutant of su(2) + su(3) of real dimension 2, span{1, i}): (2, 3)_{1/6}.
(2) Under (S): C^2 (x) Lambda^0 W and C^2 (x) Lambda^3 W have weights 3 and -3 (Y = +1/2, -1/2), total mode
    numbers 1 (odd) and 4 (even); su(3) acts on Lambda^3 W by its trace, 0, so both are (2, 1). Without (S), in
    Lambda^3(C^2 (x) C^3) the SU(2)-orbit of a filled row spans rank 4 (five unipotent images), and the raising
    operator e satisfies e^3(row) = 6 e_01^e_02^e_03, e^4 = 0: one Jordan block, the quadruplet (4, 1), weight +3.
(3) Single-spinor sector Lambda^k C^3: weights 0, -2, -4, -6 (Y = 0, -1/3, -2/3, -1); the sl(3) weights
    (mod (1,1,1)) of Lambda^1 are those of 3, of Lambda^2 those of 3bar (the negatives), Lambda^0 and Lambda^3 are
    trivial: 1, 3, 3bar, 1. The composite content is (2,3)_{1/6} + (2,1)_{-1/2}.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from tp_premise import premise

QI = GA.QI
XY = [QI(0, 3), QI(0, 3)]           # diagonal of the C^2 part of y
YY = [QI(0, -2), QI(0, -2), QI(0, -2)]   # diagonal of the C^3 part of y
UNIP = [F(0), F(1), F(2), F(3), F(5)]


def _basis_su(n):
    out = []
    for k in range(n - 1):
        out.append({(k, k): QI(0, 1), (k + 1, k + 1): QI(0, -1)})
    for j in range(n):
        for k in range(j + 1, n):
            out.append({(j, k): QI(1), (k, j): QI(-1)})
            out.append({(j, k): QI(0, 1), (k, j): QI(0, 1)})
    return out


def _tensor(X, Y, m, k):
    M = {}
    for (a, c), z in X.items():
        for b in range(k):
            M[(a * k + b, c * k + b)] = M.get((a * k + b, c * k + b), QI(0)) + z
    for (b, d), z in Y.items():
        for a in range(m):
            M[(a * k + b, a * k + d)] = M.get((a * k + b, a * k + d), QI(0)) + z
    return {kk: v for kk, v in M.items() if v}


def _diag(vals):
    return {(i, i): v for i, v in enumerate(vals) if v}


def _scalar(M, N):
    c = M.get((0, 0), QI(0))
    return c if all(M.get((i, j), QI(0)) == (c if i == j else QI(0)) for i in range(N) for j in range(N)) else None


def _wedge_weight(diag, S):
    return sum((diag[i] for i in S), QI(0))


def _commutant_real_dim(gens, N):
    """Real dimension of {Z in M_N(C) : [Z, g] = 0 for all g}."""
    cols = []
    for r in range(N):
        for c in range(N):
            for part in (QI(1), QI(0, 1)):
                Z = {(r, c): part}
                row = []
                for g in gens:
                    C = {}
                    for (a, b), z in Z.items():
                        for (b2, d), w in g.items():
                            if b == b2:
                                C[(a, d)] = C.get((a, d), QI(0)) + z * w
                    for (a, b), w in g.items():
                        for (b2, d), z in Z.items():
                            if b == b2:
                                C[(a, d)] = C.get((a, d), QI(0)) - w * z
                    for i in range(N):
                        for j in range(N):
                            v = C.get((i, j), QI(0))
                            row.extend([v.re, v.im])
                cols.append(row)
    return 2 * N * N - GA.rank_of_vectors(cols)


def _wedge3(vecs):
    out = {}
    for I in combinations(range(6), 3):
        m = [[vecs[r][c] for c in I] for r in range(3)]
        d = (m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1]) - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
             + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]))
        if d:
            out[I] = d
    return out


def _row_state(s):
    vecs = []
    for a in range(3):
        v = [F(0)] * 6
        v[a] = s
        v[3 + a] = F(1)
        vecs.append(v)
    return _wedge3(vecs)


def _apply_e(state):
    out = {}
    for I, c in state.items():
        for pos, cell in enumerate(I):
            if cell >= 3:
                new = list(I)
                new[pos] = cell - 3
                if len(set(new)) < 3:
                    continue
                sign, arr = 1, new[:]
                for x in range(3):
                    for y in range(2 - x):
                        if arr[y] > arr[y + 1]:
                            arr[y], arr[y + 1] = arr[y + 1], arr[y]
                            sign = -sign
                out[tuple(arr)] = out.get(tuple(arr), F(0)) + sign * c
    return {k: v for k, v in out.items() if v != 0}


def _sl3(w):
    s = F(sum(w), 3)
    return tuple(F(x) - s for x in w)


def check_cells_are_quark_doublet():
    premise("standard-model.global-form-quotient-determined")
    y2, y3 = _diag(XY), _diag(YY)
    # y is central in s(u(2) + u(3)) and traceless on C^5
    gens = [_tensor(X, {}, 2, 3) for X in _basis_su(2)] + [_tensor({}, Y, 2, 3) for Y in _basis_su(3)]
    ycell = _tensor(y2, y3, 2, 3)
    ok = sum(XY + YY, QI(0)) == QI(0)
    w = _scalar(ycell, 6)
    ok = ok and w == QI(0, 1) and F(w.im, 6) == F(1, 6)
    ok = ok and _commutant_real_dim(gens, 6) == 2
    GA.check("cells C^2 x C^3: y acts as i (q = 1, Y = 1/6), irreducible: (2,3)_{1/6}", ok)
    return ok


def check_doublets_under_s():
    premise("standard-model.hyp-s-slot-statistics")
    premise("standard-model.imported-pair-systems-two-chirality-halves")
    ok = True
    w0 = _scalar(_diag(XY), 2)                                  # C^2 x Lambda^0 W
    w3 = _scalar(_diag([x + _wedge_weight(YY, (0, 1, 2)) for x in XY]), 2)   # C^2 x Lambda^3 W
    ok = ok and w0 == QI(0, 3) and w3 == QI(0, -3)
    ok = ok and (F(w0.im, 6), F(w3.im, 6)) == (F(1, 2), F(-1, 2))
    # su(3) on Lambda^3 C^3 acts by its trace: zero for every generator, so an SU(3) singlet
    ok = ok and all(sum((Y.get((i, i), QI(0)) for i in range(3)), QI(0)) == QI(0) for Y in _basis_su(3))
    modes = [1 + 0, 1 + 3]
    ok = ok and [m % 2 for m in modes] == [1, 0]
    GA.check("under (S): C^2 x Lambda^0 W weight 3 (odd), C^2 x Lambda^3 W weight -3 (even), both (2,1)", ok)
    return ok


def check_no_doublet_without_s():
    premise("standard-model.raw-representation-content-state-space")
    premise("standard-model.imported-cauchy-decomposition-exterior-power")
    states = [_row_state(s) for s in UNIP]
    keys = sorted(set(k for st in states for k in st))
    rk = GA.mat_rank([[st.get(k, F(0)) for k in keys] for st in states])
    filled = _row_state(F(0))
    e1 = _apply_e(filled)
    e2 = _apply_e(e1)
    e3 = _apply_e(e2)
    e4 = _apply_e(e3)
    cell_w = _scalar(_tensor(_diag(XY), _diag(YY), 2, 3), 6)
    ok = rk == 4 and len(keys) == 8 and e3 == {(0, 1, 2): F(6)} and e4 == {} and len(e1) == 3 and len(e2) == 3
    ok = ok and (cell_w * QI(3)) == QI(0, 3)
    GA.check("without (S) the filled rows form the quadruplet (4,1) of weight +3 (rank 4, one Jordan block)", ok)
    return ok


def check_single_spinor_sector():
    premise("standard-model.imported-pair-systems-two-chirality-halves")
    ok = True
    weights = []
    for k in range(4):
        ws = [_wedge_weight(YY, S) for S in combinations(range(3), k)]
        ok = ok and all(x == ws[0] for x in ws)
        weights.append(ws[0].im)
    ok = ok and weights == [0, -2, -4, -6] and [F(x, 6) for x in weights] == [0, F(-1, 3), F(-2, 3), -1]
    sl = [sorted(_sl3(tuple(int(i in S) for i in range(3))) for S in combinations(range(3), k)) for k in range(4)]
    three = sorted(_sl3(tuple(int(i == j) for i in range(3))) for j in range(3))
    three_bar = sorted(tuple(-x for x in w) for w in three)
    ok = ok and sl[0] == sl[3] == [(0, 0, 0)] and sl[1] == three and sl[2] == three_bar and three != three_bar
    GA.check("Lambda^k C^3: weights 0, -2, -4, -6 and content 1, 3, 3bar, 1", ok)
    return ok

standard-model.ten-transported-ambient-s:
"""standard-model.ten-transported-ambient-space-doublets-are: exact checks.

The module Lambda(C^5) in the occupation basis e_S (pairs 1, 2, 3; rungs 4, 5); v_a creates mode a,
w_a contracts it. S(U(2) x U(3)) acts through its Lie algebra: hypercharge y acts on e_S by
3j - 2k (j occupied rungs, k occupied pairs, Y = y/6), 2T_3 = N_4 - N_5, su(2) = span(v_4 w_5,
v_5 w_4, N_4 - N_5), su(3) = span(v_a w_b (a != b <= 3), N_1 - N_2, N_2 - N_3). Commutators are
computed as operators on all 32 basis states.
(1) [y, v_a] = 3 v_a on rungs and -2 v_a on pairs, opposite on w_a: Y = +-1/2 on rung vectors,
-+1/3 on pair vectors; [2T_3, v_4] = v_4, [2T_3, v_5] = -v_5, 2T_3 kills pair vectors; v_1 w_2 sends
v_2 to v_1 and w_1 to -w_2 and kills rung vectors.
(2) The ten splits into the four invariant blocks span(v_4, v_5), span(w_4, w_5), span(v_1..v_3),
span(w_1..w_3): [v_a w_b, v_c] = delta_bc v_a and [v_a w_b, w_c] = -delta_ac w_b for all a, b, c, so
su(2) acts only on rung blocks, su(3) only on pair blocks, each irreducibly (raising maps reach every
basis vector); the su(3) Cartan weights are those of 3 on the v's and of 3bar on the w's.
(3) The one-mode states: (1,0) twice with Y = 1/2, (0,1) three times with Y = -1/3.
(4) In GA, Cl(5,5) with v_a = (e+_a + e-_a)/2, w_a = (e+_a - e-_a)/2 satisfies the null-pair relations,
the Fock operators satisfy the same relations, the rung pairs span hyperbolic planes and the pair
vectors span W + Wbar with W, Wbar maximal isotropic: the ten is the complexified ambient space.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from tp_premise import premise

N = 5
STATES = [frozenset(c) for r in range(N + 1) for c in combinations(range(1, N + 1), r)]
RUNGS, PAIRS, MODES = (4, 5), (1, 2, 3), (1, 2, 3, 4, 5)


def act(op, st):
    out = {}
    for (kind, i), c in op.items():
        for S, a in st.items():
            if kind == "v" and i not in S:
                T = S | {i}
            elif kind == "w" and i in S:
                T = S - {i}
            else:
                continue
            sign = -1 if sum(1 for j in S if j < i) % 2 else 1
            out[T] = out.get(T, 0) + sign * c * a
    return {k: v for k, v in out.items() if v != 0}


def lin(*terms):
    out = {}
    for c, st in terms:
        for k, v in st.items():
            out[k] = out.get(k, 0) + c * v
    return {k: v for k, v in out.items() if v != 0}


def V(a):
    return lambda st: act({("v", a): F(1)}, st)


def W(a):
    return lambda st: act({("w", a): F(1)}, st)


def prod(A, B):
    return lambda st: A(B(st))


def comm(A, B):
    return lambda st: lin((1, A(B(st))), (-1, B(A(st))))


def acomm(A, B):
    return lambda st: lin((1, A(B(st))), (1, B(A(st))))


def scaled(c, A):
    return lambda st: lin((c, A(st)))


def diag_op(f):
    return lambda st: {S: f(S) * a for S, a in st.items() if f(S) != 0}


def same(A, B):
    return all(A({S: F(1)}) == B({S: F(1)}) for S in STATES)


def zero_op(st):
    return {}


def ident(st):
    return dict(st)


Y6 = diag_op(lambda S: 3 * len(S & set(RUNGS)) - 2 * len(S & set(PAIRS)))
T3x2 = diag_op(lambda S: (4 in S) - (5 in S))


def num(a):
    return diag_op(lambda S: 1 if a in S else 0)


def check_weights_by_commutators():
    ok = True
    for a in RUNGS:
        ok = ok and same(comm(Y6, V(a)), scaled(3, V(a))) and same(comm(Y6, W(a)), scaled(-3, W(a)))
    for a in PAIRS:
        ok = ok and same(comm(Y6, V(a)), scaled(-2, V(a))) and same(comm(Y6, W(a)), scaled(2, W(a)))
        ok = ok and same(comm(T3x2, V(a)), zero_op) and same(comm(T3x2, W(a)), zero_op)
    ok = ok and same(comm(T3x2, V(4)), V(4)) and same(comm(T3x2, V(5)), scaled(-1, V(5)))
    ok = ok and same(comm(T3x2, W(4)), scaled(-1, W(4))) and same(comm(T3x2, W(5)), W(5))
    g = prod(V(1), W(2))
    ok = ok and same(comm(g, V(2)), V(1)) and same(comm(g, W(1)), scaled(-1, W(2)))
    ok = ok and all(same(comm(g, X(a)), zero_op) for X in (V, W) for a in RUNGS)
    GA.check("ten: Y = +-1/2 on rung vectors, -+1/3 on pair vectors; 2T_3 and the su(3) generator v_1 w_2", ok)
    return ok


def check_four_multiplets():
    premise("standard-model.imported-tower-commuting-copies-fock-module")
    ok = True
    n = 0
    for a in MODES:
        for b in MODES:
            g = prod(V(a), W(b))
            for c in MODES:
                ok = ok and same(comm(g, V(c)), V(a) if b == c else zero_op)
                ok = ok and same(comm(g, W(c)), scaled(-1, W(b)) if a == c else zero_op)
                n += 2
    ok = ok and n == 250
    # irreducibility: raising and lowering connect every basis vector of each block
    ok = ok and same(comm(prod(V(4), W(5)), V(5)), V(4)) and same(comm(prod(V(5), W(4)), V(4)), V(5))
    ok = ok and same(comm(prod(V(4), W(5)), W(4)), scaled(-1, W(5)))
    ok = ok and all(same(comm(prod(V(a), W(b)), V(b)), V(a)) for a in PAIRS for b in PAIRS if a != b)
    # su(3) Cartan weights (H_1, H_2) = (N_1 - N_2, N_2 - N_3): 3 on v, 3bar on w
    H1 = lambda st: lin((1, num(1)(st)), (-1, num(2)(st)))
    H2 = lambda st: lin((1, num(2)(st)), (-1, num(3)(st)))
    wts = {1: (1, 0), 2: (-1, 1), 3: (0, -1)}
    for a, (p, q) in wts.items():
        ok = ok and same(comm(H1, V(a)), scaled(p, V(a))) and same(comm(H2, V(a)), scaled(q, V(a)))
        ok = ok and same(comm(H1, W(a)), scaled(-p, W(a))) and same(comm(H2, W(a)), scaled(-q, W(a)))
    GA.check("ten: (2,1)_{1/2} + (2,1)_{-1/2} + (1,3)_{-1/3} + (1,3bar)_{1/3}", ok)
    return ok


def check_one_mode_states_form_the_five():
    one = [S for S in STATES if len(S) == 1]
    data = sorted((len(S & set(RUNGS)), len(S & set(PAIRS)), F(3 * len(S & set(RUNGS)) - 2 * len(S & set(PAIRS)), 6))
                  for S in one)
    ok = data == [(0, 1, F(-1, 3))] * 3 + [(1, 0, F(1, 2))] * 2
    GA.check("ten: the one-mode states are (1,0) twice with Y = 1/2 and (0,1) three times with Y = -1/3", ok)
    return ok


def check_ten_is_the_complexified_ambient_space():
    premise("standard-model.imported-tower-commuting-copies-fock-module")
    premise("standard-model.imported-fock-model-twistor-space")
    sq = [F(1)] * 5 + [F(-1)] * 5
    half = F(1, 2)
    gv = {a: GA.scal(half, GA.add(GA.gen(a - 1), GA.gen(a + 4))) for a in MODES}
    gw = {a: GA.scal(half, GA.sub(GA.gen(a - 1), GA.gen(a + 4))) for a in MODES}
    ok = True
    for a in MODES:
        for b in MODES:
            d = F(1) if a == b else F(0)
            ok = ok and GA.eq(GA.add(GA.mul(gv[a], gv[b], sq), GA.mul(gv[b], gv[a], sq)), {})
            ok = ok and GA.eq(GA.add(GA.mul(gw[a], gw[b], sq), GA.mul(gw[b], gw[a], sq)), {})
            ok = ok and GA.eq(GA.add(GA.mul(gv[a], gw[b], sq), GA.mul(gw[b], gv[a], sq)), GA.sc(d))
            # the same relations hold for the Fock operators
            ok = ok and same(acomm(V(a), V(b)), zero_op) and same(acomm(W(a), W(b)), zero_op)
            ok = ok and same(acomm(V(a), W(b)), ident if a == b else zero_op)
    ten = [gv[a] for a in MODES] + [gw[a] for a in MODES]
    G = [[GA.dot(x, y, sq) for y in ten] for x in ten]
    ok = ok and GA.mat_rank(G) == 10
    # rung pairs: hyperbolic planes; pair vectors: W and Wbar totally isotropic of dimension 3
    for a in RUNGS:
        ok = ok and [[GA.dot(x, y, sq) for y in (gv[a], gw[a])] for x in (gv[a], gw[a])] == [[0, half], [half, 0]]
    ok = ok and all(GA.dot(gv[a], gv[b], sq) == 0 and GA.dot(gw[a], gw[b], sq) == 0 for a in PAIRS for b in PAIRS)
    GA.check("ten: the mode vectors span the complexified ambient space, rung planes hyperbolic", ok)
    return ok

standard-model.under-s-bracket-direction:
"""standard-model.under-s-bracket-direction-charged-not: exact checks.

The five-mode module Lambda(C^5) (pair modes 0, 1, 2 = W, rung modes 3, 4 = R_2), exact, with
6Y = 3 N_R - 2 N_W, 2T_3 = n_3 - n_4, the colour Cartan n_0, n_1, n_2, and the invariant pairing
B (a state paired only with its complement). Checked:
(1) the two-mode states Lambda^2(R_2 + W): sectors (2,0) x 1, (1,1) x 6, (0,2) x 3 with Y = 1, 1/6,
    -2/3; their T_3 values {0}, {+-1/2} and colour weights (singlet, triplet e_i, antitriplet
    -e_i mod the trace): (1,1)_1 + (2,3)_{1/6} + (1,3bar)_{-2/3}, the 10 of SU(5) as
    e^c + Q + u^c; the slot bivector state is the e^c direction with T_3 = 0, Y = 1, charge 1;
    (a) it is not neutral: a condensate there breaks electromagnetism.
(2) (b) under U(5) (raising operators E_ab, a < b, acting on the ten mode vectors v_a -> weight
    e_a, w_a -> -e_a, extended to exterior powers), the number of highest-weight vectors of the
    weight of the 10 of SU(5) (e_1 + e_2 modulo the trace) is 0 in 10_v = Lambda^1, 1 in
    120 = Lambda^3 and 1 in Lambda^5 = 126 + 126bar (one of the two halves; which half is the
    convention of Fact standard-model.imported-spinor-bilinears and is not recomputed).
(3) (b) the couplings through the pairing on the sixteen: the 10_v and Lambda^5 couplings
    B(psi, x phi) are symmetric, the Lambda^3 (120) couplings antisymmetric, so they vanish on one
    generation (psi = phi); the 120 coupling in the bracket direction (w_0 w_1 w_2, the e^c weight
    modulo the trace) is nonzero and joins L with L, antisymmetrically. (c) follows: no one-generation mass operator from the bracket
    direction.
"""
from fractions import Fraction as F
from itertools import combinations

import GA
from pyutil import get_or_set
import fock
from tp_premise import premise

# ---------------------------------------------------------------------------
# The five-mode module Lambda(W + R_2) = Lambda(C^5), exact. States are bitmasks 0..31, mode m
# occupied when bit m is set; modes 0, 1, 2 are the pair modes (W), modes 3, 4 the rung (slot)
# modes, the text's v_4, v_5. Operators are sparse matrices {(row, col): number}; creation has the
# Jordan-Wigner sign (-1)^(occupied modes below m). Sector of a state: (j, k) = (rung number,
# pair number); 6Y = 3j - 2k. The invariant pairing B(psi, phi) pairs a state only with its
# complement.
# ---------------------------------------------------------------------------
NM, DIM, FULL = 5, 32, 31
PAIRS, SLOTS = (0, 1, 2), (3, 4)
SPECIES = {(0, 0): "nu^c", (0, 2): "u^c", (1, 1): "Q", (1, 3): "L", (2, 0): "e^c", (2, 2): "d^c"}


def nr(s):
    return sum(1 for m in SLOTS if s >> m & 1)


def nw(s):
    return sum(1 for m in PAIRS if s >> m & 1)


def sector(s):
    return (nr(s), nw(s))


mm, madd, msc, comm = fock.mm, fock.madd, fock.msc, fock.comm


ONE = fock.eye(DIM)
VOP = [fock.cre(m, NM) for m in range(NM)]  # v_m, creation
WOP = [fock.ann(m, NM) for m in range(NM)]  # w_m, annihilation
NUM = [fock.num(m, NM) for m in range(NM)]
YOP6 = madd(msc(3, madd(NUM[3], NUM[4])), msc(-2, madd(NUM[0], NUM[1], NUM[2])))   # 6Y
T3OP2 = madd(NUM[3], msc(-1, NUM[4]))                                               # 2 T_3
EVEN = [s for s in range(DIM) if (nr(s) + nw(s)) % 2 == 0]


def ad_weight(H, x):
    """The eigenvalue of ad(H) on the operator x (None if x is not an eigenvector)."""
    c = comm(H, x)
    key, v = next(iter(x.items()))
    lam = c.get(key, 0) / v
    return lam if not madd(c, msc(-lam, x)) else None


def wedge_sign(S, T):
    sgn = 1
    for i in range(NM):
        if T >> i & 1:
            sgn *= (-1) ** bin(S >> (i + 1)).count("1")
    return sgn


def bpair(S, T):
    """B on basis states: nonzero only for T the complement of S."""
    if T != FULL ^ S:
        return 0
    k = bin(S).count("1")
    return wedge_sign(S, T) * (-1) ** (k * (k - 1) // 2)


def mass_form(c):
    """M_c(S, T) = B(S, c T) on the sixteen (even states): {(S, T): value}."""
    out = {}
    for (r, t), x in c.items():
        if t in EVEN:
            S = FULL ^ r
            if S in EVEN:
                val = bpair(S, r) * x
                if val:
                    out[(S, t)] = out.get((S, t), 0) + val
    return {key: v for key, v in out.items() if v}


def species_entries(c):
