def coupling_symmetry(x):
    """(+1 symmetric, -1 antisymmetric, 0 neither or zero) for B(S, x T) on the sixteen."""
    M = mass_form(x)
    if not M:
        return 0
    if all(M.get((T, S), 0) == v for (S, T), v in M.items()):
        return 1
    if all(M.get((T, S), 0) == -v for (S, T), v in M.items()):
        return -1
    return 0


